-- 7.4.4 퀘스트 대사 다듬기(사용자 요청): 어색한·맥락이 안 맞는 대사를 고치고, 다음 장면에서 할 일(어디서·무엇을·왜)을
-- 앞 장면 끝에서 인물이 게임 속 이름으로 맡기게 했다. 퀘스트 장면·주 이야기 결말·세력 퀘스트 장면.
-- 고친 줄 349 · 넣은 줄 166 · 지운 줄 1 · 할 일 문구 28. 원본 supabase/gen744(data/*.json, gen.py).
-- 고칠 줄이 DB와 다르면(old) 전부 되돌린다. 할 일 조건·보상·장면 수는 그대로.
create or replace function pg_temp.yh744_rebuild(src jsonb, ops jsonb, tag text) returns jsonb
language plpgsql as $f$
declare out jsonb := '[]'::jsonb; el jsonb; x jsonb; i int; n int := jsonb_array_length(src);
begin
  for x in select value from jsonb_array_elements(coalesce(ops #> '{ins,-1}', '[]')) loop out := out || jsonb_build_array(x); end loop;
  for i in 0 .. n - 1 loop
    el := src -> i;
    if ops -> 'd' ? i::text then
      if md5(el ->> 't') is distinct from ops -> 'd' ->> i::text then raise exception '% %번 줄(지우기)이 DB와 다름', tag, i; end if;
    else
      if ops -> 'e' ? i::text then
        if md5(el ->> 't') is distinct from ops -> 'e' -> i::text ->> 'old' then raise exception '% %번 줄이 DB와 다름: %', tag, i, el ->> 't'; end if;
        el := el || jsonb_build_object('t', ops -> 'e' -> i::text ->> 't');
      end if;
      out := out || jsonb_build_array(el);
    end if;
    for x in select value from jsonb_array_elements(coalesce(ops -> 'ins' -> i::text, '[]')) loop out := out || jsonb_build_array(x); end loop;
  end loop;
  for x in select key from jsonb_each(ops -> 'e') union select key from jsonb_each(ops -> 'd') union select key from jsonb_each(ops -> 'ins') loop
    if (x #>> '{}')::int >= n then raise exception '% %번 줄이 없음', tag, x #>> '{}'; end if;
  end loop;
  return out;
end $f$;

do $do$
declare st jsonb := '{"mq_red_seal/1":{"e":{"1":{"old":"9c7adaf4454c382fa740dcef3c987b76","t":"왔군요. 오늘부터 당신을 맡게 된 담당 서기관 연서희예요. 반가워요."}},"d":{},"ins":{"17":[{"s":"q:m_yeon","t":"부적 장부라도 받아 간 사람 이름이 함께 적혀요. 이름은 사람을 이 세상에 묶어 두는 명줄이라, 장부 한 쪽이 비면 그만큼 사람이 비는 거예요."}]}},"mq_red_seal/3":{"e":{"6":{"old":"8fc2bec2a8972b1fbcd9081fb436d70a","t":"잿빛 들녘 채집터에 많이 나요. 세 번 캐다가 저한테 가져다주세요. 바로 태워 볼게요."}},"d":{},"ins":{}},"mq_red_seal/4":{"e":{"5":{"old":"4a10d7b7534156161b5f0aa1e87b71e1","t":"섣부른 말은 하지 마십시오. 조사원, 폐쇄 사당을 두어 번 탐색해 보고 정청의 연 서기관에게 보고하십시오. 봉인식은 원래 그곳에서 지냈습니다."}},"d":{},"ins":{}},"mq_drowned_ledger/2":{"e":{"5":{"old":"3f76374182b1a577b2e8e63848041e5d","t":"구룡 폐수로 수문께에 수문아귀 놈들이 자리를 틀었어. 두어 놈 잡아서 뭘 물고 다니는지 보고 오게."}},"d":{},"ins":{}},"mq_drowned_ledger/3":{"e":{"5":{"old":"d814419e76b8e7a5f1656f5116c2d986","t":"염등촌 물귀신들은 비늘에 물길을 새긴다는 말이 있어. 거기서 수귀 비늘 세 장만 주워다 주면 장부가 어디로 갔는지 읽어 주지."}},"d":{},"ins":{}},"mq_drowned_ledger/5":{"e":{"1":{"old":"47e6ec6394993fa43e4718e369f77dd7","t":"나루로 돌아와 장터 기둥의 문양과 옛 정청 엽전 이야기를 적어 전서구로 띄웠다. 얼마 지나지 않아 연서희의 답장이 왔다."}},"d":{},"ins":{}},"mq_red_moon_oath/2":{"e":{"5":{"old":"22a4c1d183fa9d83a200d9313136edbf","t":"그건 말 못 해요. 대신 하나 알려 드릴게요. 우리 교에서 도망친 계집애가 하나 있는데, 적사 황무지 붉은 전갈 소굴에 숨었어요. 지금쯤 전갈 밥이 되고 있을걸요?"}},"d":{},"ins":{"2":[{"s":null,"t":"나는 정청 장부에서 사라진 이름들을 사 간 게 적월교냐고 물었다."}],"6":[{"s":null,"t":"그 아이를 찾으려면 적사 황무지의 붉은 전갈 떼부터 헤치고 들어가야 할 듯하다."}]}},"mq_red_moon_oath/3":{"e":{"3":{"old":"2bcfe89138c12c72132b02287806a671","t":"다행이다. 저는 사월이에요. 적월교 무녀였어요. 이제는 아니고요."},"6":{"old":"9e0051ac09c591b7e220661abe5eef4a","t":"안신탕 한 그릇만 만들어 줄 수 있어요? 그거라도 마시면 말할 수 있을 것 같아요. 저는 이 바위 틈에서 기다릴게요."}},"d":{},"ins":{}},"mq_frost_seal/2":{"e":{"5":{"old":"0c0729b6c4430dc0b66b5eff46dac6d8","t":"그런데 협로를 비취 수문장이 막아섰다는 소식이 있어요. 영감이 안쪽에 갇혔을지도 몰라요. 옥문 협로로 가서 수문장부터 쓰러뜨려 줘요."}},"d":{},"ins":{}},"mq_frost_seal/3":{"e":{"5":{"old":"4e4e9a18cd647c058180d27f35111be9","t":"빙혼곡 빙정염이 있어야 말뚝을 다시 박는다. 세 덩이만 캐다 나한테 가져와. 얼음 틈 아래서 캔 게 진짜다."}},"d":{},"ins":{}},"mq_eclipse_gate/1":{"e":{"8":{"old":"47d3d8233d1af1a164b26b4a043e1a1e","t":"먼저 흑사단 폐단으로 가 주세요. 명부가 아직 거기 있는지 확인해야 합니다. 흑사 주술승들이 제단을 지키고 있다니, 둘쯤은 쓰러뜨려야 들어갈 수 있을 거예요."},"4":{"old":"220c94a77a8f49203e5aa9d4bc031953","t":"무너졌어도 명부는 남아요. 부르는 사람은 없어도 글자가 남아 있으면, 그 사람들은 아직 영으로 남아 있어요. 그 마지막 가닥을 걷어 바치는 거예요."}},"d":{},"ins":{}},"mq_eclipse_gate/2":{"e":{"5":{"old":"5973d65e144ee67bfd1531ddff1e2243","t":"성에 들어가려면 교도처럼 보여야 해요. 교도들은 정화 부적을 붉은 실로 감아 허리에 차요. 이 폐단에서 부적실을 모아 정화 부적 두 장만 만들어 주세요. 백골 장터에서 제가 실을 감을게요."}},"d":{},"ins":{}},"mq_eclipse_gate/3":{"e":{"7":{"old":"1e7db6c2ef0294e575a7c795125b4daa","t":"월식은 오늘 밤이에요. 적월교 월식성 성문을 지키는 월식 파계장을 쓰러뜨려야 제단까지 길이 열립니다."}},"d":{},"ins":{}},"mq_eclipse_gate/4":{"e":{"7":{"old":"13efcbef9237f7cefd4be7a918a859a3","t":"뇌명봉으로 가라. 벼락 맞은 바위에 문의 메아리가 새겨진다. 꼭대기를 몇 번이고 뒤져 봐라. 내가 줄 수 있는 건 거기까지다."}},"d":{},"ins":{"3":[{"s":"red_moon_cult:wolhwa","t":"버리는 쪽은 따로 있는데, 줍는 우리만 늘 욕을 먹는구나."}]}},"mq_sunken_lantern/1":{"e":{"8":{"old":"0524cfe2c20af2f4556f24d83dc34570","t":"…천엽 연화늪에 가서 수향 갈대 세 대만 꺾어 오게. 갈대 피리는 물이 부르는 노래를 따라 부르지. 피리는 내가 깎아 주겠네."}},"d":{},"ins":{"7":[{"s":"river_alliance:nodeul","t":"역린은 용 목 밑에 거꾸로 난 비늘이여. 용잠 수궁 깊은 데 그런 비늘 하나가 문처럼 물길을 잠가 두고 있다는 게지."}]}},"mq_sunken_lantern/2":{"e":{"5":{"old":"1b2296c3eeaf738812bb4a9ea6f2da32","t":"수경루엔 수경무희들이 밤새 춤을 춘다던데요. 둘만 쓰러뜨려도 춤이 멎고 거울이 맑아질 거예요. 뱃삯은 깎아 드릴 테니 꼭 부탁드려요."}},"d":{},"ins":{}},"mq_sunken_lantern/3":{"e":{"6":{"old":"dc36c2455f78f1262d58598b14668d0f","t":"수궁은 깊어요. 빛이 없으면 길을 잃어요. 어유 등잔을 하나 만들어 용잠 수궁으로 들고 가요. 물 밑에서도 꺼지지 않는 불이 필요해요."},"2":{"old":"ac3de87ce13b6e9effec315d90fe6017","t":"저 사람들… 장부에서 지워진 이름들이에요. 붉은 인장과 함께 사라진 부적 기록에 있던 사람도 보여요. 아직 흩어지지 않은 걸 보면, 누군가 저 이름들을 붙들고 있나 봐요."}},"d":{},"ins":{}},"mq_sunken_lantern/4":{"e":{"7":{"old":"f09cb12d86cd33dad372e1f9ff2fdf81","t":"수궁 해일장이 문 앞을 막고 있다. 저것이 깨어 있는 한 나는 등딱지를 들 수가 없다. 그대가 눕혀 주게."}},"d":{},"ins":{"6":[{"s":"q:m_gaon","t":"그자는 이름을 물에 풀기 전에 하나하나 낮게 불러 주더군. 저 행렬이 흩어지지 않은 건, 누군가 오래 그렇게 불러 왔기 때문일 게다."}]}},"mq_ash_sea/1":{"e":{"5":{"old":"01dcdf0d6198eb29a655628d1ed1e09a","t":"해안에 그 배가 남아 있을지도 몰라요. 갈매 대장과 함께 재의 해안을 몇 번이고 뒤져 주세요."},"1":{"old":"82b579a9ce489b5e69c438021f709878","t":"나라가 망하던 밤에도 등대는 꺼지지 않았소. 그런데 지난달부터 하나씩, 하나씩 꺼져 가고 있소."}},"d":{},"ins":{}},"mq_ash_sea/2":{"e":{"6":{"old":"c20ff0adfba2fcf8f202b9a8266d3078","t":"장 장군이 등대를 다시 켤 쇠틀을 만든대. 주혈 광산에서 생 월철 네 덩이를 캐다 잔불촌의 장군께 갖다 줘. 갱도 원령들이 길을 막을 테니 두엇은 쓰러뜨려야 할 거야."}},"d":{},"ins":{}},"mq_ash_sea/3":{"e":{"2":{"old":"d7231483fde4e8d26df83c3861acb5f0","t":"장군님, 광산 원령들이 「돌려 달라」고 울부짖었대요. 무엇을 돌려 달라는 걸까요."},"5":{"old":"b120e3f3bc1ac859fa0c1bdd66df6d36","t":"쇠틀은 다 됐소. 허나 구등대 군도까지는 물살이 사나워 배가 못 가오. 원정을 꾸려 끝까지 건너가시오. 남은 세 등대는 등대지기 하나가 홀로 섬을 돌며 지킨다 들었소."},"3":{"old":"67369765b96ee1f80eceef47bf28ea7a","t":"이름이오. 저 광산에서 죽은 우리 백성들은 장부에 이름 한 줄 못 남겼소. 망국의 백성은 어느 장부에서든 먼저 지워지지."},"4":{"old":"8e945f13e73f94a730fca228090a38ad","t":"…그래서 흑련회가 그 이름을 쓸 수 있었군요. 아무도 찾지 않는 이름이니까. 이름도 없이 원한만 남아서 원령이 된 거고요."}},"d":{},"ins":{}},"mq_ash_sea/4":{"e":{"6":{"old":"4d77973e2c1e9d439532d94ad793abdd","t":"세 섬을 혼자 돌다 보니 기름이 다 떨어져서, 이 불도 곧 꺼져요. 등대 불은 영기가 뭉친 응축 영핵이 있어야 다시 커져요. 하나만 만들어 주실 수 있어요?"},"0":{"old":"19360de5f2c4907c496b187d00736c69","t":"안개를 헤치고 군도의 가장 바깥 섬에 닿는다. 등대 꼭대기에서 작은 불씨 하나가 흔들리고, 기름통을 진 사람이 막 계단을 내려온다."},"2":{"old":"a1e0ee557510ebdd36aef975658313dc","t":"저는 도화예요. 아홉 등대지기 가운데 마지막으로 남았어요. 다른 여덟은… 명령서를 받고 스스로 불을 끄고 떠났어요. 남은 세 등대는 제가 섬을 돌아가며 지켜요."}},"d":{},"ins":{}},"mq_lamp_shadow/1":{"e":{"7":{"old":"f43b87abcc10cd1957c18e93654bb54e","t":"연화원 관리 명부는 장서각에 있었는데, 몇 해 전에 통째로 젖어서 버렸다고 들었어요. 그 무렵부터 백지교 아래로 종이학이 떠내려온다는 말이 돌았고요."}},"d":{},"ins":{"7":[{"s":"night_office:han","t":"조사원, 백지교를 세 번쯤 뒤져 건질 수 있는 건 다 건져 와라. 모 기록관은 정청으로 불러 두겠다."}],"0":[{"s":null,"t":"남쪽에서 전서구가 먼저 닿아 있었다. 도화가 홀로 힘겹게 지키던 세 등대 가운데 둘이 결국 꺼졌다. 마지막 하나만 아직 버틴다."},{"s":"q:m_yeon","t":"꺼진 등대가 여덟이면 열린 문도 여덟이에요. 남은 건 도화 씨가 지키는 불 하나뿐이고요."}]}},"mq_lamp_shadow/2":{"e":{"5":{"old":"c60630cf2bf1a08f9d74dbfc7f75673d","t":"거둔 먹은 영맥 수피 즙에 담그면 다시 떠올라요. 귀죽림 영맥 수피가 가장 진하니, 세 장만 벗겨 와 주세요."}},"d":{},"ins":{"4":[{"s":"night_office:mo","t":"서희야, 이제 너도 알아야겠다. 정청은 해마다 오래된 이름을 명부에서 거둬. 「명부 정리」라고, 우리 서리들은 「먹 거두기」라 부르지."},{"s":"q:m_yeon","t":"…거둬요? 무슨 기준으로요?"},{"s":"night_office:mo","t":"부를 사람도, 제사를 이을 사람도 없는 이름부터. 낡은 쪽부터. 거둔 이름은 아무 데도 묶이지 않아. 그게 지워진 이름이야."}]}},"mq_lamp_shadow/3":{"e":{"5":{"old":"264a146dbb8780b0e548829aa23308a3","t":"서류에 없는 점검이다. 조사원, 지금 폐쇄된 연화원으로 가라. 봉인이 풀렸다면 연화원 봉인파쇄귀가 먼저 깨어 있을 거다. 나는 정청 문을 닫는다."}},"d":{},"ins":{}},"mq_lamp_shadow/5":{"e":{"1":{"old":"d3dcbff04973f7773d06b28e740a3aff","t":"나는 달여 온 안신탕을 건네며 마시라고 했다."}},"d":{},"ins":{"3":[{"s":null,"t":"연서희가 붓을 들어 출납 장부 맨 끝 빈칸을 한참 내려다본다. 끝내 아무것도 적지 못한다."}]}},"mq_nine_gates/1":{"e":{"1":{"old":"4900f3a2c9d75076511b9c3ab727bb25","t":"아, 오셨군요. 졸려 보이나요? 사실은 사흘째 못 잤어요. 별이 꺼지는 순서가 등대가 꺼진 순서랑 똑같아요. 남은 별은 하나예요."},"5":{"old":"11c495482b702362a4346d3c39700b23","t":"빈 길을 채우려면 별모래가 있어야 해요. 백옥 천문탑에서 성진사를 세 줌만 담아 와 주세요. 탑 별빛을 먹은 모래라, 그걸 뿌리면 빈 길이 그려질 거예요."}},"d":{},"ins":{}},"mq_nine_gates/2":{"e":{"0":{"old":"1c2d9c67c61230e7ff7cc8acb0769460","t":"서이연이 담아 온 성진사를 지도 위에 흩뿌린다. 별빛 먹은 모래알이 스스로 굴러가 빈 길을 채운다."},"5":{"old":"a94267f22d374682c7cb237829777de1","t":"흑조 균열에 역천 표류체가 모여들고 있어요. 문이 열리며 밀려 나온 것들이에요. 둘만 치워도 아래로 내려갈 길이 열릴 거예요."}},"d":{},"ins":{}},"mq_nine_gates/3":{"e":{"6":{"old":"8ae758956f1af4f1fa28295e2bf73975","t":"봉연은 오래 내려가야 해요. 회생 부적을 한 장 만들어 품고, 원정을 꾸려 구중 봉연 끝까지 내려가요."}},"d":{},"ins":{}},"mq_red_seal/2":{"e":{"3":{"old":"422bd95f287f48f64516eb64e0046bc1","t":"그런데 요 며칠 책벌레 요괴가 들끓어서 남은 쪽까지 갉아 먹고 있어요. 글자를, 특히 이름을 갉아 먹고 사는 놈들이라 장부엔 제일 해로워요."}},"d":{},"ins":{"2":[{"s":"night_office:mo","t":"해마다 오래된 쪽을 거둘 때도 이렇게 반듯하게 잘라 내긴 해요. 그런데 이건 거둘 쪽이 아니었어요. 작년에 적은 거거든요."}]}},"mq_red_moon_oath/4":{"e":{"2":{"old":"b1eebc4b701de429ec21750203fcd9c4","t":"이름이 지워진 사람은 아무도 찾지 않잖아요. 장부에도 없고 불러 줄 사람도 없으니, 그 이름은 누구에게도 묶여 있지 않대요. 제물로 쓰기 가장 좋은 거죠."}},"d":{},"ins":{"6":[{"s":"q:m_sawol","t":"이름이 지워지면 살아 있어도 없는 사람이 돼요. 아무도 안 찾고, 끝내는 저도 저를 잊겠죠."},{"s":"q:m_sawol","t":"유리협곡에 가 보세요. 서약에 오른 이름은 그곳 유리벽에 먼저 새겨진대요. 두어 번 살펴보면 보일 거예요."},{"s":"q:m_sawol","t":"저는 정청으로 몰래 보내 주세요. 다 보고 나면 백골 장터로 돌아가세요. 단비 언니와의 내기는 거기서 끝내야 하니까요."}]}},"mq_red_moon_oath/5":{"e":{"3":{"old":"d903bd6c3dec4acfd92ce6ce69f63cff","t":"괜찮아요. 그 애 이름 하나 빠진다고 서약이 무너지진 않거든요. 이름은 많으니까요. 정청 장부에 아주 많았죠. 오래된 쪽일수록 지키는 사람이 없던데요?"}},"d":{},"ins":{}},"mq_nameless_bell/3":{"e":{"1":{"old":"5ea9e29ea5d68b191404237ca34b555a","t":"그 나무들은 저희 조상 이름을 하나씩 달고 있던 나무예요. 이름이 붙어 있는 동안엔 조상 영이 깃든 신목이었죠. 종소리를 듣고 그 이름을 잃은 거예요."}},"d":{},"ins":{"2":[{"s":"southern_remnant:soi","t":"이름을 다 잃으면 사람이든 영이든 요괴가 돼요. 그때부턴 아무도 이름으로 안 불러요. 혈엽수인, 그렇게 갈래로만 부르죠."}]}},"mq_nameless_bell/5":{"e":{"6":{"old":"317eafdf5dea734072e4cf73afc59ec9","t":"무명은 이름이 아니라 빈칸이에요. 신원 모를 시신도, 명부에서 지워진 사람도, 이름을 맡긴 사람도 장부엔 다 「무명」으로 적히죠. 회주님은 그 말을 호칭으로 쓰실 뿐이에요."},"4":{"old":"0514a70fd88a5d5fda66fb4b19e098b5","t":"하나만 덤으로 드리죠. 우리 회주님은 그 종소리를 들어 본 분이에요. 그 뒤로 제 이름을 회원 장부 깊숙이 넣어 두고 다시 꺼내지 않으세요."}},"d":{},"ins":{"6":[{"s":"black_lotus:guseul","t":"명줄은 매듭이라 풀어서 남한테 맡길 수 있어요. 맡긴 사람은 그 이름으로 불려도 돌아보지 못하지만, 저희가 회원 장부에 적어 지키니 요화하진 않아요. 저희 장사가 그거예요."}]}},"mq_eclipse_gate/5":{"e":{"3":{"old":"41af8739994622e7b0b232c2becd903d","t":"…다 세셨군요. 잊지 않아 주셔서 고마워요. 누가 세어 주고 기억해 주면, 그만큼은 덜 사라지는 거래요."}},"d":{},"ins":{}},"mq_lamp_shadow/4":{"e":{"5":{"old":"981a0e8184d85f5b6353fe46adb49782","t":"바친 게 아닙니다. 돌려보낸 거예요. 망국의 백성, 흑사단, 등대지기들. 해마다 명부 정리에서 맨 먼저 거둬지는 이름들이지요."},"3":{"old":"7b3f2ad719e3f20a846563757819297b","t":"연화원의 스물두 번째 관리. 제 이름은 제가 지웠습니다. 흑련회 사람들은 그런 저를 무명이라 부르더군요."}},"d":{},"ins":{"8":[{"s":null,"t":"연서희가 물가에 주저앉는다. 쥔 손이 멈추지 않고 떨린다. 정청으로 돌아가 안신탕이라도 한 그릇 달여 먹여야겠다."}],"5":[{"s":"q:m_yun","t":"그 먹을 십오 년 동안 제 손으로 거뒀습니다. 그래서 밤마다 그 이름들을 몰래 불렀지요. 수경루 물 밑의 행렬이 여태 흩어지지 않은 건 그 덕입니다."},{"s":"q:m_yun","t":"그래도 이 세상 어느 장부도 그들을 다시 적어 주지 않아요. 문 너머에는 지워진 이름이 전부 모여 있습니다. 마지막 문을 열면 데려올 수 있어요."}],"3":[{"s":"q:m_yeon","t":"무명이라니… 신원 모를 시신한테나 적는 말이잖아요."}]}},"mq_nine_gates/4":{"e":{"1":{"old":"9a83e627107e73482d555d4b7258cec9","t":"지나온 문들이 차례로 보인다. 종이 걸린 첫 문, 붉은 실이 끊어진 둘째 문, 비늘이 돌아간 셋째 문, 그리고 꺼진 등대 불빛이 비친 문 다섯."}},"d":{},"ins":{}},"mq_drowned_ledger/4":{"e":{},"d":{},"ins":{"5":[{"s":"river_alliance:nodeul","t":"장부 쪽에 적힌 게 다 사람 이름 아닌가. 물 위엔 이름을 사고파는 장사꾼도 있다더구먼."},{"s":"river_alliance:nodeul","t":"침수된 구시가지에 가서 두어 번 뒤져 보게. 값을 매긴 놈이 뭐라도 흘렸을 게야. 다 보거든 나한테 다시 들르고."}]}},"mq_frost_seal/4":{"e":{},"d":{},"ins":{"6":[{"s":"q:m_baekmu","t":"말뚝은 박았으니 잔도는 버틴다. 원정을 꾸려 얼음 너머까지 한 번 끝까지 다녀와라. 뭐가 뒤척이는지 네 눈으로 보고, 철벽 고찰에 가서 맹주한테 전해."}],"5":[{"s":"q:m_baekmu","t":"말뚝 머리마다 먼저 간 말뚝지기 이름이 새겨져 있다. 내 이름도 저 끝에 있지. 이름이 붙어 있어야 말뚝이 안 풀린다더라."}]}},"mq_nameless_bell/2":{"e":{},"d":{},"ins":{"5":[{"s":"southern_remnant:soi","t":"혈엽림에 가서 미쳐 날뛰는 혈엽수인 셋만 잠재워 주세요. 그래야 끌린 자국을 따라가 볼 수 있어요. 저는 여기서 기다릴게요."}]}},"mq_nameless_bell/4":{"e":{},"d":{},"ins":{"5":[{"s":"southern_remnant:soi","t":"끌린 자국은 만인장으로 이어졌다고 했죠. 그곳 비석들 사이를 세 번쯤 살펴보시고, 그다음엔 십삼문 암시장으로 가세요. 흑련회 땅에서 소문을 살 수 있는 곳은 거기뿐이에요."}]}},"mq_nine_gates/5":{"e":{},"d":{},"ins":{"5":[{"s":"q:m_yeon","t":"명부 정리도, 먹 거두기도 이제 알아요. 돌아가면 거둔 이름도 숫자로라도 남기게 할게요. 출납관님이 그랬던 것처럼요."}]}},"sq_field_outskirts_1/1":{"e":{"4":{"old":"c06a26af258749721831c6f84d89f7f0","t":"그걸 알면 내가 쫓아갔지. 일단 들녘에 나오는 이삭 도깨비부터 세 마리쯤 혼내 주시오. 놈들을 잡으면 뭐라도 나오겠지."}},"d":{},"ins":{}},"sq_field_outskirts_1/2":{"e":{"3":{"old":"40eafb1603cb911df5e6b0555c1ae9a3","t":"나는 잿빛 들녘을 두어 번 더 살펴 이삭 다발이 가던 곳을 찾아보겠다고 했다."}},"d":{},"ins":{}},"sq_field_outskirts_2/1":{"e":{"4":{"old":"062cf47743988b1206f8facdcdb0affd","t":"들녘 둑길 아래요. 야령초 세 포기, 약제 바탕 두 개면 충분해요. 쥐떼가 다니는 길이니까 조심하세요."}},"d":{},"ins":{}},"sq_field_outskirts_2/2":{"e":{"1":{"old":"872db64c5bbae62cce46b0d85911b38f","t":"그런데 저 혼자서는 손이 모자라요. 다친 분들 드실 영초 차를 한 번만 달여서 가져다주실래요?"}},"d":{},"ins":{}},"sq_hq_dorm_1/1":{"e":{"2":{"old":"fffac9e0d97d76ac9b2e08da891aad63","t":"잿빛 들녘에 나가서 야령초 세 줌만 뜯어 오구려. 나물로 섞으면 속이 든든해."}},"d":{},"ins":{}},"sq_hq_dorm_1/2":{"e":{"1":{"old":"903f1fc662d6bdcbc81286c4c25c6f88","t":"이번엔 직접 노정 건량 두 꾸러미를 싸서 내게 맡겨 보우. 건량 싸는 법은 조사원이면 다 알아야 해."}},"d":{},"ins":{}},"sq_hq_dorm_2/1":{"e":{"4":{"old":"91a62fd6750f705267c3c5d0c2650a00","t":"내 눈엔 그렇게 보였소. 잿빛 들녘을 몇 번 훑어보면 뭐라도 떨어져 있을 거요. 한 감찰관께는 아직 말씀 못 드렸소."}},"d":{},"ins":{}},"sq_hq_dorm_2/3":{"e":{"1":{"old":"3631c74224c526bc56ee2cc2642c679c","t":"그런데도 그자는 방에 들었습니다. 누군가 문을 열어 주었다는 뜻이지요."}},"d":{},"ins":{}},"sq_hq_training_1/1":{"e":{"2":{"old":"f6bb57ca453b4eba8f8715b4d1f1626e","t":"농담이고, 목인귀가 씌었다. 허수아비 귀까지 덩달아 일어났지. 목인귀 두 놈, 허수아비 귀 두 놈만 부수고 오너라. 훈련 삼아서!"}},"d":{},"ins":{}},"sq_hq_training_2/1":{"e":{"2":{"old":"21d6473618c3be8250fa4077fbcdc283","t":"연무장 둘레에서 부적목을 세 번만 베어다 주세요. 깎는 건 직접 해 보시고요."}},"d":{},"ins":{}},"sq_hq_training_2/2":{"e":{"2":{"old":"174f774cb6f11e7950537b93f22b443b","t":"쥐떼가 또 오기 전에 화살을 두 번 깎아 주세요. 다 깎으면 과녁 쥐떼도 두 마리쯤 쫓아 주시고요. 새 화살까지 갉으면 안 되니까요."}},"d":{},"ins":{}},"sq_hq_training_2/3":{"e":{"0":{"old":"295c20f67c32edf5047b5ba090909cc5","t":"쥐떼가 달아났네요. 직접 깎은 화살로 쏘니까 손에 감이 오죠?"}},"d":{},"ins":{}},"sq_hq_yard_1/1":{"e":{"1":{"old":"53ad3e54fa3deeb2ffb49e7a20bfaa60","t":"황지 세 장이랑 부적실 두 타래가 필요해요. 폐쇄 사당 쪽에서 나는 게 질이 좋아요."}},"d":{},"ins":{}},"sq_hq_yard_1/2":{"e":{"1":{"old":"d1745103675f2375a328a93dcc5b0333","t":"문수가 황지를 등불에 비춰 보더니 조심스레 품에 안는다."},"2":{"old":"584c97fc4458ff13cdbb6e0540165474","t":"이제 이걸로 정화 부적 두 장을 만들어 주셔야 해요. 저는 붓을 쥐면 손이 떨려서요."}},"d":{},"ins":{}},"sq_hq_yard_2/1":{"e":{"2":{"old":"83db27f314656ce0737a763afe0679cb","t":"금줄식귀가 그 줄을 먹고 불어나고, 금줄 까마귀까지 꼬였습니다. 폐쇄 사당에서 금줄식귀 둘, 금줄 까마귀 둘을 정리하고 남은 줄을 그 자리에서 확인하십시오."}},"d":{},"ins":{}},"sq_hq_yard_2/2":{"e":{"1":{"old":"99879fb436f12c3572ab8e5066453896","t":"매듭을 꼰 손은 하나다. 같은 버릇이 일곱 번 되풀이되어 있다."}},"d":{},"ins":{"2":[{"s":null,"t":"나는 남은 금줄을 챙겼다. 본부 정청으로 돌아가 한설에게 보일 때다."}]}},"sq_lantern_market_1/1":{"e":{"0":{"old":"d437a69f8aa609e1b697bd0488682204","t":"어이구, 손님이 아니라 조사원이로구먼. 차 한 잔 하겠수? 아이고, 미안하우. 찻잎이 떨어져서 물밖에 없네."},"2":{"old":"9b7d8075ee54ebbcbbb3ebb84428356e","t":"잿빛 들녘에서 야령초를 네 번만 뜯어다 주면, 내가 영초 차 달이는 법을 가르쳐 주리다."}},"d":{},"ins":{}},"sq_lantern_market_1/2":{"e":{"2":{"old":"dd35f7352bf9a038232f0fbc24de28eb","t":"자, 불은 약하게, 물은 넉넉히. 끓기 직전에 내리는 거유. 이대로 영초 차를 두 번 달여서 가져와 보우."}},"d":{},"ins":{}},"sq_lantern_market_2/1":{"e":{"2":{"old":"bb28a88f387d97cb3d20516d58b905ce","t":"새로 짜려면 월철이 필요하오. 잿빛 들녘 바위틈에 광석이 드러난 데가 있소. 월철 광석 세 덩이, 생 월철 두 덩이면 되겠소."}},"d":{},"ins":{}},"sq_lantern_market_2/2":{"e":{"2":{"old":"b22173edcd9a172caa61d71c9528feeb","t":"뼈대를 짜 둘 테니 잠시 뒤 다시 오시오. 다시 켤 때 첫 불은 자네가 붙여 주시오."}},"d":{},"ins":{}},"sq_hq_archive_1/1":{"e":{"2":{"old":"f8b1894535685f0f6c1a6311eac225a2","t":"정제 황지 세 장이랑 먹정 두 개만 있으면 메울 수 있어요. 지하서고 안쪽 습한 데 많아요. 벌레도 많고요."},"3":{"old":"c6585e07844010dedff9125c6ff32687","t":"아, 책벌레 요괴는 보이는 대로 두어 마리 잡아 주시고요!"}},"d":{},"ins":{}},"sq_hq_archive_2/1":{"e":{"2":{"old":"e0943f14ac12a5df3bd74201643a0141","t":"누가 또 왔다는 거죠. 뭘 찾으러 왔을까요? 지하서고를 몇 번만 샅샅이 뒤져 주세요. 흔적이 남았을지도 몰라요."}},"d":{},"ins":{}},"sq_shrine_ruins_1/1":{"e":{"1":{"old":"14cd69f945fadd4c9544f2dee51f1196","t":"조사원님, 제 방울 못 보셨어요? 산문이 무너질 때 깨졌어요."},"3":{"old":"e3b2dd7d420daf76f9ac9c49ecd0bcca","t":"결계 파편 세 조각이랑, 방울에 서렸던 기운이 굳은 요기 결정 두 개를 모아 주세요. 그러면 다시 울릴 수 있을지도 몰라요."}},"d":{},"ins":{"1":[{"s":"q:dh_gaeul","t":"놀라지 마세요. 제 몸은 오래전에 없어요. 그래도 마을 할머니들이 아직 제 이름을 불러 주셔서, 이렇게 영으로 남아 있어요."}]}},"sq_shrine_ruins_2/1":{"e":{"2":{"old":"cd2eb5aea64173e4fd44fc6980aac7e3","t":"언니를 아프게 하지 말라고는 못 하겠어요. 그냥… 쉬게 해 주세요. 언니는 한 번 쓰러져도 다시 일어나요. 두 번은 눕혀야 해요."}},"d":{},"ins":{"2":[{"s":"q:dh_gaeul","t":"언니 곁엔 촛농 도깨비불이 늘 붙어 다녀요. 그것도 두엇은 꺼 주셔야 언니한테 닿을 수 있어요."}]}},"sq_shrine_ruins_2/2":{"e":{"2":{"old":"c2527a3f84c24ebc918fde5a72a77278","t":"산문 파쇄귀예요. 방울 소리가 나면 오는 게 바로 저거예요. 언니 말이 맞았어요. 저것만 쓰러뜨려 주시면 방울을 다시 울릴 수 있어요."}},"d":{},"ins":{}},"sq_shrine_ruins_2/3":{"e":{"2":{"old":"208f14c5b3736a6bee8f23267e7e8d0a","t":"이제는 언니도 무서워하지 말고 들어 줬으면 좋겠어요. 이 소리요."}},"d":{},"ins":{}},"sq_old_canal_1/1":{"e":{"1":{"old":"6d8f9b7802d5e5490e74f65f37e93ab7","t":"수문 열 시간까지 기다려야 하는데 배가 고파서 원. 여기 폐수로에서 고기 세 마리만 낚아 주겠나?"},"3":{"old":"49b611555692658daa403ef17a9b6efd","t":"수문은 이십 년 전에 쇳물로 때워 닫혔다. 노인은 그 일을 모르는 사람처럼 말한다."}},"d":{},"ins":{}},"sq_old_canal_1/2":{"e":{"2":{"old":"2374cebdf30b71d83b1c9091a8834e77","t":"손질한 생선 두 접시만 차려 주게. 내 손은 요즘 칼을 못 쥐어."}},"d":{},"ins":{}},"sq_old_canal_2/1":{"e":{"2":{"old":"dc381cbc77ed95017b8789e1b3321c20","t":"배를 갈라 보면 아직 남아 있을 걸세. 놈 위장은 느려. 폐수로에 수문아귀가 여럿이니 세 놈쯤은 잡아 봐야 할 걸세."}},"d":{},"ins":{}},"sq_old_canal_2/3":{"e":{"2":{"old":"96808c266c5230cbfa33337cb01bfaac","t":"오십 년 노를 저어 보니 장부 들고 도망치는 손님은 늘 같은 얼굴이더군. 뒤를 자꾸 돌아보는 얼굴."}},"d":{},"ins":{}},"sq_paper_bridge_1/1":{"e":{"2":{"old":"e6270ae2491a8c44b76025b393d3a57f","t":"그런데 종이가 떨어졌어요. 이 다리에서 정제 황지 세 장이랑 황지 두 장만 구해 주실래요? 고운 종이로 접어야 잘 날거든요."}},"d":{},"ins":{}},"sq_paper_bridge_1/2":{"e":{"2":{"old":"52dcccafae568844628d3249af974d61","t":"저 종이학 무리가 제 학을 먹어요. 다 접기 전에 세 마리만 쫓아 주세요."}},"d":{},"ins":{}},"sq_paper_bridge_2/1":{"e":{"2":{"old":"cf8660092a9b718488583ff8ced31923","t":"백지교에서 네 번쯤 낚아 보세요. 먹물 메기가 아니어도 이 물에 사는 고기라면 먹이 배어 있을 거예요. 비린 건… 참을게요."}},"d":{},"ins":{}},"sq_sealed_garden_1/1":{"e":{"1":{"old":"89e43fb8fa0bc11b1698639db89240c6","t":"정원이 닫히기 전에 제가 가꾸던 밭이 있어요. 거기서 월광 이끼 세 줌, 영맥 수피 두 조각만 거둬다 주세요. 아직 자라고 있을 거예요."}},"d":{},"ins":{}},"sq_sealed_garden_2/1":{"e":{"2":{"old":"add94d71c0f055f2eadac38b07181ad4","t":"약제 바탕은 연화원 안에서 나요. 두 번만 캐서 안신탕을 한 사발 지어다 주세요."}},"d":{},"ins":{}},"sq_west_gate_1/1":{"e":{"2":{"old":"aad672537d4e2e1d04dae0a1f3f3cb2d","t":"녹슨 창이 되어서도 지나가는 사람을 찌르네. 녹슨 창귀 둘, 성문 파수망령 둘이 아직 성벽을 돌아. 그만 쉬게 해 주게."}},"d":{},"ins":{}},"sq_west_gate_1/2":{"e":{"1":{"old":"63bc502711dc87acd4e93448c77586a3","t":"그런데 대장이 남았네. 성루에 숨어 지나는 이를 노리는 성루 매복병, 그게 우리 대장이야."}},"d":{},"ins":{}},"sq_west_gate_2/1":{"e":{"1":{"old":"a858923219a6845900d9ba8fa0b866dd","t":"날이 다 상했어. 이 성벽 돌틈에 쇠가 나니, 월철 광석 두 덩이랑 생 월철 두 덩이만 캐 주겠나?"}},"d":{},"ins":{}},"sq_west_gate_2/2":{"e":{"1":{"old":"24c42a932e2d6e379fd67e46bae540b7","t":"이걸로 월철 주괴를 하나 녹이고, 장비 수리 도구도 하나 만들어 주게. 수리 도구는 내가 받아 두겠네."}},"d":{},"ins":{}},"sq_ghost_bamboo_2/1":{"e":{"1":{"old":"5fa6468f9a12e596bb0a9b32c386ce62","t":"대숲 독은 독으로 다스리는 법이지. 독낭, 약제 바탕, 영맥 수피를 두 개씩만 구해 오게."},"2":{"old":"6c7ee28bcbde296bc3cfb4744fea92a7","t":"셋 다 귀죽림 안쪽에서 나네. 나는 물린 놈들 지키느라 못 가."}},"d":{},"ins":{}},"sq_ghost_bamboo_2/2":{"e":{"1":{"old":"9f3d9387352cc203a659f3ef0af7b314","t":"이제 청령단 두 알만 지어다 주게. 독을 빼고 나면 기운이 빠지거든."}},"d":{},"ins":{}},"sq_sunken_district_1/2":{"e":{"0":{"old":"6827a3e6c1a1f03d9f543926095c06d7","t":"쥐떼와 상여귀가 흩어지자 물길이 열린다. 빈 상여 하나가 떠내려간 뒤로 관아 지붕 끝이 보인다."}},"d":{},"ins":{"2":[{"s":"q:dh_wolsun","t":"장군님은 물에 잠겼다가도 다시 일어나세요. 두 번은 눕혀 드려야 함을 놓으실 거예요."}]}},"sq_sunken_district_2/1":{"e":{"2":{"old":"6f130c11b9b2ee89583f68090f1643b4","t":"어유 등잔이면 물 밑까지 비춘대요. 기름은 물고기에서 나와요. 여기서 물고기 세 마리만 낚아 주실래요?"}},"d":{},"ins":{}},"sq_sunken_district_2/2":{"e":{"1":{"old":"f8a5ab15a4432c8633396911eeede0e9","t":"어유 등잔 만드는 건 제가 못 해요. 조사원님이 하나만 만들어 주세요."}},"d":{},"ins":{}},"sq_river_ferry_1/1":{"e":{"4":{"old":"8963d5d469ec29d1d1599e3d3123e4b5","t":"나야 모르지요. 손님이 직접 낚싯대 한번 담가 보시겠소? 이 나루에서 네 마리만 올려 보시오. 고기가 올라오면 노래 탓은 아니란 뜻이니."}},"d":{},"ins":{}},"sq_river_ferry_1/2":{"e":{"3":{"old":"f69c45111ab5ba378c1d6a35bb9d4f26","t":"영감님, 또 그 소리. 손님, 그 고기로 생선구이 두 접시만 구워 주시오. 나 혼자 상 차리기엔 손이 모자라서."}},"d":{},"ins":{}},"sq_river_ferry_2/1":{"e":{"3":{"old":"26b9890963f88cee224e44d6a47de223","t":"그 배가 들렀을 곳은 구룡 폐수로뿐입니다. 폐수로에 가서 세 번쯤 샅샅이 살펴 주세요."}},"d":{},"ins":{}},"sq_salt_village_1/1":{"e":{"3":{"old":"838cc39e895a56cd78b986208d07c15d","t":"모르겠어요. 그래서 부탁드려요. 염전에 서는 소금각시를 쓰러뜨려 주세요. 각시 곁을 맴도는 염전 갈매기 두 마리도요. 그리고 언니인지 알려 주세요."}},"d":{},"ins":{}},"sq_shrine_ruins_1/2":{"e":{"2":{"old":"282d309c80051af61ca74abee12fdc9d","t":"방울먹는 무녀귀가 가져갔어요. 저랑 같이 일하던 언니였는데… 불러 줄 사람이 다 떠나서 이름을 잃었어요. 이젠 다들 무녀귀라고만 불러요."}},"d":{},"ins":{}},"sq_field_outskirts_1/3":{"e":{"2":{"old":"dfd75ea600596887bbd4a1f540aabc11","t":"도깨비들이 그 녀석 대신 제 몫을 챙겨 온 모양이오. 못 받은 품삯이 남았으니, 그 녀석 이름도 아직 이 들녘을 못 떠난 게지."}},"d":{},"ins":{}},"sq_hq_dorm_2/2":{"e":{},"d":{},"ins":{"3":[{"s":"q:dh_cheol","t":"이건 내가 쥐고 있을 물건이 아니오. 본부 정청의 한설 감찰관께 가져다드리시오."}]}},"sq_hq_archive_2/2":{"e":{},"d":{},"ins":{"2":[{"s":"night_office:mo","t":"서고 어딘가에 탈명 죽간이 더 숨어 있을 거예요. 두 개만 찾아서 부숴 주세요. 그래야 먹힌 이름이 돌아와요."}]}},"sq_old_canal_2/2":{"e":{},"d":{},"ins":{"2":[{"s":"river_alliance:nodeul","t":"폐수로를 두어 번 더 훑어보게. 아래쪽 수문엔 수문 거머리왕이 버티고 있지. 떠내려온 건 죄다 그놈 몸에 들러붙는다네."}]}},"sq_paper_bridge_2/2":{"e":{},"d":{},"ins":{"2":[{"s":"night_office:mo","t":"글자로 엉기는 먹이라니! 그 고기를 손질한 생선으로 두 번 만들어 주세요. 살에 밴 먹을 걸러 볼게요."}]}},"sq_sealed_garden_2/2":{"e":{},"d":{},"ins":{"2":[{"s":"q:dh_seonhwa","t":"연화원을 두어 번 살펴봐 주세요. 밭가에 덩굴 손이 엉겨 있다던데, 두엇만 걷어 내면 누가 물을 줬는지 보일지도 몰라요."}]}},"sq_ghost_bamboo_1/1":{"e":{},"d":{},"ins":{"2":[{"s":"q:dh_cheongun","t":"가는 길목엔 대나무 원숭이들이 숨어 있다가 덮쳐요. 귀죽림을 두어 번 살피면서 원숭이 세 마리만 쫓아 주세요. 그러면 노래 나는 쪽을 찾을 수 있을 거예요."}]}},"sq_ghost_bamboo_1/2":{"e":{},"d":{},"ins":{"2":[{"s":"q:dh_cheongun","t":"그럼 노래 주인이 대숲 독사녀라는 거예요? 숲 안쪽에 산다던 그 뱀 여자요… 부탁이에요, 그걸 쓰러뜨려 주세요."}]}},"sq_sunken_district_1/1":{"e":{},"d":{},"ins":{"2":[{"s":"q:dh_wolsun","t":"장군님께 가려면 먼저 길부터 터야 해요. 구시가지 골목에 이끼 쥐떼랑 물 먹은 상여귀가 들끓거든요. 두 마리씩만 치워 주세요."}]}},"sq_river_ferry_2/2":{"e":{},"d":{},"ins":{"3":[{"s":null,"t":"그림자 뱃사공이다. 나는 저것들을 두엇 쓰러뜨리고 흔적을 하나 더 찾아, 구름나루의 매향에게 가져가기로 했다."}]}},"sq_salt_village_1/2":{"e":{},"d":{},"ins":{"3":[{"s":"q:sn_okbun","t":"염전 끝 소금 더미에 숨어 지나는 이를 덮치는 염전 매복귀가 있어요. 그 그림자가 그놈 같아요. 그걸 쓰러뜨려 주세요."}]}},"sq_hq_archive_1/2":{"e":{},"d":{},"ins":{"3":[{"s":"night_office:mo","t":"해마다 오래된 쪽은 거둬 내야 서가가 버텨요. 그러니 남길 건 이렇게 이어 붙여서라도 살려 둬야죠."}]}},"sq_salt_village_2/1":{"e":{"2":{"old":"e0cfaa4513e6696913ecea8e3aa671ed","t":"염등촌 갯가 채집터에서 농축 약초액을 세 번만 걷어다 주시겠소? 갯풀에서 짜낸 것이라 청정수 밑감으로 맞소."}},"d":{},"ins":{}},"sq_salt_village_2/2":{"e":{"1":{"old":"d7d41365329dd8af27876fee38237cf5","t":"한 번 걸러 청정수로 달여야 하오. 청정수 두 병만 만들어 이 약방으로 가져다주시겠소?"}},"d":{},"ins":{}},"sq_lotus_marsh_1/1":{"e":{"2":{"old":"c24ac091bc89916546d8cdd2e488fd2e","t":"저 혼자는 무서워서요. 조사원님이 이 늪 채집터에서 월광 이끼를 세 번만 걷어 와 주시면 안 될까요?"}},"d":{},"ins":{}},"sq_lotus_marsh_1/2":{"e":{"3":{"old":"9a8a0fbd3f4b39c2fe78c156f791f15c","t":"우선 약부터요. 늪가에서 야령초를 세 번 더 캐 주세요. 야령초 둘에 이끼 둘을 저한테 주시면 그걸로 달일게요."}},"d":{},"ins":{}},"sq_lotus_marsh_2/1":{"e":{"0":{"old":"3a17d1f19d239d5a3b31267416b16587","t":"내 열을 내려 준 분이구려. 염치없지만 하나만 더 부탁하겠소."},"1":{"old":"5d7b0f4770b5e5f5f23e83d1db5d32be","t":"연밭을 갉는 연근식귀를 두 마리만이라도 없애 주시오. 저것들이 연밭을 다 갉으면 올겨울은 굶소."}},"d":{},"ins":{}},"sq_lotus_marsh_2/2":{"e":{"3":{"old":"be4b340eef78027b260f28289d526303","t":"나는 부적을 받아먹던 것이 따로 있을 거라고 하고, 늪 한가운데의 연못 독두꺼비를 찾아가 보자고 했다."}},"d":{},"ins":{}},"sq_lotus_marsh_2/3":{"e":{"1":{"old":"d9b7ec6d77d8be5bd19a9040a1edbd33","t":"흉년 한 번 없이 삼십 년이었소. 대신 늪은 해마다 독해졌지. 내가 독에 쏘인 것도 다 내 탓이오."}},"d":{},"ins":{}},"sq_mirror_pavilion_1/1":{"e":{"2":{"old":"ef868ad8a0806eb4df8d30ced7a5fc5b","t":"호수 물거울에는 비친다더이다. 누각 물가에서 귀경 파편을 세 번만 주워 와 주시오. 깨진 거울 조각이라 물거울 빛을 그대로 담고 있으니 보고 그릴 수 있을 게요."}},"d":{},"ins":{}},"sq_mirror_pavilion_1/2":{"e":{"1":{"old":"68e8dbdb3c8788946226760e006db095","t":"흩어져 있군. 이어 붙이려면 요기 결정이 두 줌은 있어야겠소. 그런데 물거울 요정들이 그 둘레를 맴돌며 놓질 않지."},"2":{"old":"c741f895088d0f0e109cfa4d2a4b885f","t":"나는 물거울 요정 두 마리를 물리치고 요기 결정을 두 번 모아 오겠다고, 그때 파편 세 조각도 함께 건네겠다고 했다."}},"d":{},"ins":{}},"sq_mirror_pavilion_2/1":{"e":{"0":{"old":"0d6e724da1b4624d627b8eb74cbdf296","t":"초상을 다 그린 뒤로 밤마다 그림 속에서 발소리가 들리오."},"2":{"old":"dc6d4269a41c875568cce46fcd9f61db","t":"정화 부적을 붙이면 잠잠해지려나. 내 손으로는 접을 수가 없으니, 세 장만 만들어 주시겠소?"}},"d":{},"ins":{}},"sq_mirror_pavilion_2/2":{"e":{"3":{"old":"43a0f8a14e4c7169506c76d91f292684","t":"나는 부적보다 저 거울 속 무희장을 먼저 쓰러뜨려야겠다고 했다. 부적 두 장은 그 뒤에 화공에게 맡기기로 했다."}},"d":{},"ins":{}},"sq_sunken_palace_1/1":{"e":{"2":{"old":"5749052996d7725448630099e424d59c","t":"그래도 시신이라도. 용궁 시녀귀들이 문 앞을 막고 있어 저 혼자는 못 들어갑니다. 두 마리만 걷어 내 주십시오."}},"d":{},"ins":{}},"sq_sunken_palace_1/2":{"e":{"2":{"old":"c6b78288155d774787d479d53b2735ad","t":"더 안쪽으로 끌려갔습니다. 용잠 수위가 지키는 문 너머로요. 그 수위를 쓰러뜨려야 들어갈 수 있습니다."}},"d":{},"ins":{}},"sq_sunken_palace_2/1":{"e":{"2":{"old":"369e0d70dabd421938fd172845e46671","t":"용잠 수궁 물에서 고기를 네 마리쯤 낚아 보시오, 등롱어가 섞여 올라올 거요. 값은 넉넉히 치르리다. 이번만은 깎지 않겠소."}},"d":{},"ins":{}},"sq_ember_village_1/1":{"e":{"1":{"old":"cb753bfaba70e28f2292a5da1833fded","t":"손은 모자라고 땔감은 더 모자라요. 부적목부터 세 번만 해다 주시구려. 잔불촌 둘레 채집터에도 있어요."}},"d":{},"ins":{}},"sq_ember_village_1/2":{"e":{"0":{"old":"a7850dbfbb499c1306752158a3a5d9a1","t":"복례가 받아 든 부적목을 아궁이에 넣고, 깊숙한 곳의 불씨를 부지깽이로 살살 일으킨다. 작지만 꺼지지 않는 붉은빛이다."},"2":{"old":"be71244f4706b7142cad39e9b7c10a4a","t":"자, 이 불로 노정 건량 세 개를 지어 갈매 대장한테 건네주시오. 짓는 법은 어렵지 않아요."}},"d":{},"ins":{}},"sq_ember_village_2/1":{"e":{"2":{"old":"e2c8656762680da77502735de9780556","t":"다시 벼리려면 월철 광석 세 번, 생 월철 두 번은 캐야 합니다. 잔불촌 둘레 채집터든 어느 산이든 상관없으니 좀 구해 주십시오."}},"d":{},"ins":{}},"sq_ember_village_2/2":{"e":{"1":{"old":"d6f195bcdafd6aa2e8c56e1371b484b5","t":"제 풀무는 장군님 칼 녹이는 데 써야 하니, 월철 주괴 두 개는 조사원님이 만들어 주시겠어요?"}},"d":{},"ins":{}},"sq_ash_coast_1/1":{"e":{"2":{"old":"3d2b40cec0ad25b17bba29038dc3a814","t":"수향 갈대로 엮고 수귀 비늘로 추를 달면 버틴다더군. 이 해안에도 그게 나오니, 갈대부터 채집터에서 세 번 베어다 주시오."}},"d":{},"ins":{}},"sq_ash_coast_1/2":{"e":{"2":{"old":"0cad7e42b89e514ad9c2ea2717af1024","t":"비늘은 재갈매기 떼가 물어 가기 전에 주워야 하오. 저놈들을 두 떼쯤 쫓아내고 수귀 비늘을 두 번 주워다, 갈대와 함께 내게 주시오."}},"d":{},"ins":{}},"sq_ash_coast_2/1":{"e":{"2":{"old":"a1e38e38914d57d8aa2f29cf215c3c6d","t":"본부 사람인 당신이 재의 해안을 훑어 그 배를 뒤져 보시오. 우리가 하면 또 남명회가 꾸몄다 할 테니."}},"d":{},"ins":{}},"sq_crimson_mine_1/1":{"e":{"0":{"old":"bb9a5071bb19330cebf2c2bcfb4b6743","t":"막장이 무너진 지 여섯 해요. 그런데 밤마다 그 안에서 곡괭이 소리가 들리오."},"2":{"old":"68f36169bc83d7ae5700c817557cc01e","t":"가는 길엔 광석 지네가 들끓소. 세 마리만 쓰러뜨려 길부터 터 주시오. 나는 뒤따라가겠소."}},"d":{},"ins":{}},"sq_crimson_mine_1/3":{"e":{"2":{"old":"042acd879bb84d18f1b09f212cac146b","t":"맨 안쪽에 주혈 광맥왕이 있을 거요. 그날 막장을 무너뜨린 게 그놈이오. 그놈을 쓰러뜨려 주시오."}},"d":{},"ins":{}},"sq_crimson_mine_2/1":{"e":{"2":{"old":"4ab4de638160c8e6a63813fa9e7325db","t":"내 손으로 캐야 하는데 팔이 떨려 곡괭이를 못 들겠소. 막장 채집터에서 월철 광석 세 번, 생 월철 두 번만 캐 주시오."}},"d":{},"ins":{}},"sq_crimson_mine_2/2":{"e":{"2":{"old":"6d8eb2b10dab184da3d1bce8517b4255","t":"잔불촌까지 같이 가 주시오. 광석 세 덩이와 생 월철 두 덩이는 당신이 가족들한테 건네주시오. 혼자 가면 문 앞에서 돌아설 것 같소."},"1":{"old":"4e853ce6dd8d47b66a01458fb80d4347","t":"나는 생 월철까지 섞였으니 값이 꽤 나가겠다고 말했다."}},"d":{},"ins":{}},"sq_crimson_mine_2/3":{"e":{"0":{"old":"b66c238f851fe686718bc7a975eaac3c","t":"광부 가족들이 마당에 모인다. 내가 광석과 생 월철을 건네는 동안 맹구는 고개를 들지 못하고 이름 적힌 자루만 내민다."}},"d":{},"ins":{}},"sq_red_forest_1/1":{"e":{"2":{"old":"7273f71efef41ea34e2ad723aad04e36","t":"나는 동료 곁을 지켜야 하니, 이 숲 채집터에서 영맥 수피와 약제 바탕을 두 번씩만 모아 주시오."}},"d":{},"ins":{}},"sq_red_forest_1/2":{"e":{"2":{"old":"23881f427d69bf588bf246afe2a7b872","t":"회춘단 두 알은 조사원께서 빚어, 하나만 내게 주시오. 내 손이 지금 좀 떨려서."}},"d":{},"ins":{}},"sq_red_forest_2/1":{"e":{"2":{"old":"9bd979b1b2bc4f84167a8bfc66d8711c","t":"낙엽 원령이 숲길을 막아 정찰대도 못 지나가오. 먼저 세 놈만 치워 주시오."}},"d":{},"ins":{}},"sq_red_forest_2/2":{"e":{"2":{"old":"717f9ec8a9c8cafc6cae06025e8d76b8","t":"숲 한가운데 혈엽수인이 잎을 붙잡고 있을 거예요. 그 곁엔 늘 단풍 독거미가 지키고요. 둘 다 쓰러뜨려 주세요."}},"d":{},"ins":{}},"sq_nine_lighthouse_1/1":{"e":{"1":{"old":"5f29f296a27b2199d9f2fb84c33c3fef","t":"등잔은 제가 걸 수 있는데 기름이 없어요. 아버지는 바닷고기 기름을 썼어요."},"2":{"old":"1ab2495fc1eb1290b60df52209266bad","t":"군도 물에서 고기를 세 마리 낚아 등롱 어유 두 병만 내 주실 수 있어요? 등잔 만드는 것도 좀 가르쳐 주시고요."}},"d":{},"ins":{}},"sq_nine_lighthouse_1/2":{"e":{"2":{"old":"cdbc1552d9e2b162e9e475e32346d4a3","t":"이제 등잔이에요. 아버지 등잔은 바다에 떨어졌으니, 이 어유로 어유 등잔을 하나 새로 만들어 주세요."}},"d":{},"ins":{}},"sq_nine_lighthouse_1/3":{"e":{"3":{"old":"4c98de41b858df4852b822684786f5fb","t":"나는 별순에게 물러서 있으라고 하고, 꺼진 등대지기를 쓰러뜨린 뒤 등잔을 건네주겠다고 했다."}},"d":{},"ins":{}},"sq_nine_lighthouse_2/1":{"e":{"2":{"old":"d6d8d745d3387b2c04ea6358a412b5ce","t":"북쪽과 남쪽 종이 한 쌍이라면, 남쪽 종은 이 군도 어딘가에 있어야 해요. 등대 둘레를 같이 뒤져 봐 주세요."}},"d":{},"ins":{}},"sq_bone_market_1/1":{"e":{"4":{"old":"253184d46e3698e55eb31c75c265186f","t":"그건 내 알 바 아니고. 이 뼈에선 적사 황무지 모래 냄새가 나는구려. 누가 거기서 빚을 받으러 다니는지 황무지를 좀 뒤져 봐 주시오."}},"d":{},"ins":{}},"sq_bone_market_2/1":{"e":{"4":{"old":"a3be0c6f4426cf6b5fbc6e96b71f7db2","t":"화살 세 대면 되오. 더 깎아 주면 고맙고! 아, 적사 독수리가 덤벼드는 길이니 촉은 단단하게."}},"d":{},"ins":{}},"sq_bone_market_2/2":{"e":{"2":{"old":"ea582ca1e5359355462b101b02936990","t":"상단이 지나기 전에 적사 황무지 길목에서 요괴 세 마리만 쫓아 주시겠소? 화살 맛을 먼저 보여 주는 셈 치고."}},"d":{},"ins":{}},"sq_red_plain_1/1":{"e":{"3":{"old":"ad9448e3d3826d913deed50c2af96193","t":"붉은 전갈이 늘었소. 전갈이 늘면 그 밑에 큰 놈이 있지. 먼저 붉은 전갈 세 마리와 사구귀 하나부터 걷어 주시오."}},"d":{},"ins":{}},"sq_red_plain_1/2":{"e":{"1":{"old":"d8cd4f495b3403eefd457646f7c01cdd","t":"보이시오? 모래가 숨을 쉬고 있소. 모래 매복귀가 밑에서 기다리는 거요."}},"d":{},"ins":{}},"sq_red_plain_2/1":{"e":{"3":{"old":"a3de94d346015f3601041b1605787b80","t":"알아, 그래서 말하는 거요. 그 먹을 거꾸로 풀 방법이 있소. 이 황무지에서 주사 광물을 네 번, 비취 파편을 두 번 캐 주시오."}},"d":{},"ins":{}},"sq_red_plain_2/2":{"e":{"1":{"old":"9890a6e43d4ea73a943efcc0d479fe56","t":"비취는 먹을 가라앉히고, 주사는 글씨를 세우오. 둘을 함께 갈면 서약 먹과 반대가 되지."},"4":{"old":"0c762fe6ff34cf875c8c8f0abd2fd259","t":"그건 갈아 보면 알 거요. 주사 넷에 비취 둘, 내게 넘겨 주시오. 가는 건 내 손으로 하겠소."}},"d":{},"ins":{}},"sq_red_plain_2/3":{"e":{"0":{"old":"4908f03125a82626caa3159a5da7b424","t":"차돌이 돌절구에 주사와 비취를 넣고 천천히 간다. 붉은 가루가 점점 옅어진다."}},"d":{},"ins":{}},"sq_glass_canyon_1/1":{"e":{"2":{"old":"d8ca369c8f3f2e5fc68fddbfbc5ea40f","t":"큰 거울을 하나 만들어야 해요. 협곡 채집터에서 영유리 네 번, 요기 결정 두 번만 모아 주시고, 영유리는 제게 넘겨 주세요."}},"d":{},"ins":{}},"sq_black_sand_temple_1/1":{"e":{"4":{"old":"2fa7d40617f27985aa16fb9562be63c1","t":"폐단 안쪽 제단에 마른 황지가 쌓여 있습니다. 기도문을 적다 만 종이지요. 세 번쯤 걷어 오시면 넉넉할 겁니다."}},"d":{},"ins":{}},"sq_black_sand_temple_1/2":{"e":{"3":{"old":"b7a024ced6949f9fa61ad047aa8635c6","t":"나는 둘 다 아니라고 했다. 이 황지로 정화 부적 두 장을 만들어 기도를 덮어 버리면 된다고."}},"d":{},"ins":{}},"sq_black_sand_temple_2/3":{"e":{"4":{"old":"2e4bc6d198350849024a175b60360710","t":"다시 찾아간 폐단 계단에서 아이가 돌아본다. 처음으로, 부르기도 전에."}},"d":{},"ins":{}},"sq_red_moon_fort_1/1":{"e":{"4":{"old":"c00ec814c64a85751a51b86ba93f5adf","t":"네가 쓸 만한지 보자. 성벽을 한 바퀴 돌며 월식 박쥐 떼 셋과 월식 교도 둘을 눕히고 오너라."}},"d":{},"ins":{}},"sq_red_moon_fort_1/2":{"e":{"3":{"old":"b9b7e85351b234b4f0174cd43f02fdce","t":"죽이지 말고 둘만 눕혀 놔라. 깨어나면 내가 물어보겠다."},"2":{"old":"87301167327636db5749d4f99915a8a1","t":"좋다. 하나 더. 혈월 무사들이 내 말을 안 듣는다. 지난 붉은 보름 뒤로 눈빛이 이상해."}},"d":{},"ins":{}},"sq_red_moon_fort_2/1":{"e":{"2":{"old":"9148fb5f29c4256623aae880636de985","t":"마음을 가라앉히는 안신탕 두 그릇과 월광 정수 한 병이 있어야 해. 내 손은 떨려서 정수를 못 뽑는다오."},"1":{"old":"b3aa4e4a741c7720ecb1781fcb536b9c","t":"붉은 보름달을 오래 본 놈들은 꿈속에서도 달을 봐. 잠을 못 자니 눈이 돌아가는 게지."}},"d":{},"ins":{}},"sq_ash_mountain_1/1":{"e":{"2":{"old":"b35a285bfa47e473830cb8fbbf4a548f","t":"화구 근처에 생 월철이 흐르고 월철 광석도 바위째 박혀 있소. 생 월철 네 번, 월철 광석 두 번만 캐다 주시오. 잿더미 쥐떼만 아니면 내가 직접 가겠는데."}},"d":{},"ins":{}},"sq_ash_mountain_1/2":{"e":{"2":{"old":"8ca518f6fca248b1cf9d7c9426ada4c0","t":"생 월철 넷에 월철 광석 둘, 그대로 넘겨 주시오. 오늘 밤 풀무를 다시 살리겠소."},"1":{"old":"ed1e9e7585a79f9da7208a82825b243a","t":"나는 화구 열기에 달궈진 광맥이라 쇠의 질이 좋다고 말했다."}},"d":{},"ins":{}},"sq_ash_mountain_2/1":{"e":{"2":{"old":"f3c0605d49bc921eda3271bf034876c6","t":"월철 주괴를 세 개 부어, 그걸로 장비 수리 도구 하나를 만들어 주시오. 내 망치는 창에 묶여 있소."}},"d":{},"ins":{}},"sq_nine_lighthouse_1/4":{"e":{"4":{"old":"94b84f4a27fc3b8ece4a01a76c7e45c8","t":"멀리 어둠 속에서 다른 등대 하나가 대답하듯 잠깐 깜빡인다. 누군가 아직 저 불을 돌보고 있는 모양이다."}},"d":{},"ins":{}},"sq_red_moon_fort_1/3":{"e":{"1":{"old":"9449bb8a409e55403a99fa1b881f7396","t":"돌아왔군. 붉은 보름달을 너무 오래 봤나 보다."}},"d":{},"ins":{}},"sq_nine_lighthouse_2/3":{"e":{"4":{"old":"ae1cfd217b2956a6806e445a13b69ddb","t":"나는 흑련회가 종을 가져갔다면 이 군도에서 무언가를 더 꾸미고 있을 거라고 말했다."},"2":{"old":"067b1a84db2f72becdd9853ac8b4f11f","t":"저분들이 종을 울린 사람들이에요. 그래서 이름을 잃고, 이제는 등불 원령이라고만 불려요."}},"d":{},"ins":{}},"sq_sunken_palace_2/2":{"e":{},"d":{},"ins":{"2":[{"s":null,"t":"나는 낚은 고기로 등롱 어유 두 병을 내려 구름나루의 진소랑에게 가져가기로 했다."}]}},"sq_ash_coast_2/2":{"e":{},"d":{},"ins":{"3":[{"s":null,"t":"나는 난파선 망령들을 먼저 잠재우고, 일지는 잔불촌의 장무현 장군에게 가져가기로 했다."}]}},"sq_crimson_mine_1/2":{"e":{},"d":{},"ins":{"2":[{"s":"q:sn_maenggu","t":"소리 나는 쪽에 갱도 원령이 어른거리오. 두 놈만 눕혀 주시오. 가까이서 봐야겠소."}]}},"sq_nine_lighthouse_2/2":{"e":{},"d":{},"ins":{"2":[{"s":null,"t":"고리 둘레로 등불 원령들이 모여든다. 나는 저것들을 먼저 잠재우고, 고리를 떼어 간 자의 흔적을 더 찾아보기로 했다."}]}},"sq_glass_canyon_2/1":{"e":{},"d":{},"ins":{"3":[{"s":"q:rn_haerang","t":"경면쌍생은 협곡 바람귀 뒤에 숨어 다닌대요. 바람귀 둘을 먼저 걷어 내고, 같은 얼굴 둘을 다 깨 주세요."}]}},"sq_black_sand_temple_2/1":{"e":{},"d":{},"ins":{"4":[{"s":null,"t":"나는 그 명부가 아직 폐단 어딘가에 남아 있을지 모른다고 하고, 무너진 안쪽을 뒤져 보기로 했다."}]}},"sq_black_sand_temple_2/2":{"e":{},"d":{},"ins":{"4":[{"s":null,"t":"나는 이 명부를 본부 장서각 지하서고의 기록관 모가람에게 가져가겠다고 했다."}]}},"sq_iron_monastery_1/1":{"e":{"3":{"old":"d49dca58e438f4ae5b1941015e3ffac2","t":"옥문 협로 잔도엔 잔도 매복귀와 잔도 바람귀가 붙어 삽니다. 둘씩만 제 대신 눕혀 주십시오. 세게. 그래야 아이가 내려올 길이 열립니다."}},"d":{},"ins":{}},"sq_iron_monastery_1/2":{"e":{"0":{"old":"66f1ada91c163d28b681bd0e70eeeb65","t":"매복귀와 바람귀를 걷어 내자 잔도 바위 틈에서 목탁 소리가 또렷해진다."},"3":{"old":"8f9f25be5391047d799162a85413edf0","t":"나는 잘 버텼다고, 이제 철벽 고찰로 내려가자고 했다."}},"d":{},"ins":{}},"sq_iron_monastery_2/1":{"e":{"2":{"old":"98ffa91a8d47d0e79c906410bfad0b7f","t":"영사 실타래 두 타래가 있으면 다시 짤 수 있습니다. 부적실을 꼬아 영기를 먹이면 되지요."},"4":{"old":"687ca6cedee98653fe6528408f9c9c82","t":"흑사단 폐단이나 무덤가에 많습니다. 기도가 깊었던 곳에서 실도 질기지요. 세 번쯤 모아 실타래 두 타래로 지어 오십시오."}},"d":{},"ins":{}},"sq_iron_monastery_2/2":{"e":{"0":{"old":"ff0a3bdae5fe80013c994e8d471139ef","t":"정심이 실타래로 새 깃발을 짜 깃대에 단다. 바람이 불자 깃발이 소리 없이 펼쳐진다."}},"d":{},"ins":{}},"sq_jade_pass_1/1":{"e":{"3":{"old":"cd8225e661cc08df34ad24d554c56194","t":"옥문 협로에서 야령초 넷이랑 부적목 수지 둘만 캐 와. 수지는 상처에 바르고 얼음에 깨진 짐도 붙이지."}},"d":{},"ins":{}},"sq_jade_pass_2/1":{"e":{"3":{"old":"49d80c1e6f23f94356178152654e764b","t":"가 보면 알겠지. 조사원, 등불을 들고 잔도를 떠도는 청등 호송귀 둘을 꺼 줘. 놈들 뒤엔 비취 수문장이 길을 막고 있다더군."}},"d":{},"ins":{}},"sq_jade_pass_2/2":{"e":{"2":{"old":"7a3b9814b944534e55d017ba9455f40e","t":"……스승의 등롱이야. 놈들이 스승의 등불을 흉내 내서 사람을 홀렸던 거군."}},"d":{},"ins":{}},"sq_frost_valley_1/1":{"e":{"4":{"old":"9670bfa9a7faf4610e5e45d427deab70","t":"말은 됐다. 빙혼곡에서 빙정염 다섯 줌만 캐 와라."}},"d":{},"ins":{}},"sq_sky_lake_1/1":{"e":{"5":{"old":"169102a5dc1abccd68a087de0887491a","t":"고기가 올라와야 백어도 올라오는 법이지. 천경호에서 네 마리만 낚아 보게."}},"d":{},"ins":{}},"sq_sky_lake_1/2":{"e":{"2":{"old":"ecb5d7aabdb80bd0e90b2474979a82a4","t":"……허허, 사십 년을 낚았어도 남이 낚는 걸 보는 게 이리 좋을 줄은 몰랐구먼."}},"d":{},"ins":{}},"sq_sky_lake_2/1":{"e":{"2":{"old":"5c4120af338f82715192640a55fc5007","t":"그래도 먹여야지. 자네가 어죽 두 그릇만 쑤어 주게. 내 손맛이 아니니 울지 않을지도 몰라."},"3":{"old":"57f6ba3061f82f9afac9fe1bcc73782b","t":"나는 기운을 돋우게 약초 생선찜도 한 그릇 함께 만들겠다고 했다."}},"d":{},"ins":{}},"sq_thunder_peak_1/1":{"e":{"4":{"old":"a3c82b19ce320cf4701544bf1e8c00c6","t":"좋아! 뇌명봉 바위에서 응축 영핵 셋, 요기 결정 셋을 캐서 영핵 둘만 내 몫으로 줘. 아, 그리고 번쩍하면 엎드려. 생각은 그다음에."}},"d":{},"ins":{}},"sq_thunder_peak_2/1":{"e":{"3":{"old":"756e262073d7d55dabe746efb121f823","t":"산군이 그놈들 곁을 지키오. 벼락 맞고 미쳤소. 오르는 길엔 벼락 지네와 뇌석 갑귀가 들끓고."},"4":{"old":"d9dc907599c7a1d4f13a6905748f0061","t":"조사원, 길은 강파가 낸다. 넌 앞을 막는 벼락 지네 셋, 뇌석 갑귀 둘만 쳐."}},"d":{},"ins":{}},"sq_thunder_peak_2/2":{"e":{"3":{"old":"f41288c63c88bbed66413750388b62de","t":"나는 사슬을 끊기 전에 열쇠를 지키는 뇌각 산군부터 치워야겠다고 말했다."}},"d":{},"ins":{}},"sq_thunder_peak_2/3":{"e":{"3":{"old":"615b67e90879d9763f7727ce711a9f17","t":"하지만 이게 하나뿐일까. 다음 문은 물 밑에 있다고 월식성에서 들었다며. 물 밑엔 벼락이 안 닿으니, 다른 걸로 달구겠지."}},"d":{},"ins":{}},"sq_hidden_bazaar_1/1":{"e":{"4":{"old":"a77f7ef6301843af8c0f2b206f80ce95","t":"만인장. 돌 깎는 자는 돌 곁으로 간다. 가서 묘역을 세 번쯤 뒤져 봐라. 데려오든 말든, 셈만 맞추면 된다."}},"d":{},"ins":{"2":[{"s":"black_lotus:six","t":"맡긴 이름은 장부에 있다. 그 이름으로 불러도 그자는 돌아보지 못한다. 빚을 다 갚으면 돌려준다."}]}},"sq_hidden_bazaar_1/2":{"e":{"3":{"old":"21f3d3f252bfdc28a1dd8455d451e792","t":"나는 저 언덕에 무언가 있다고 생각했다. 길을 막는 것들을 두엇 쫓아내고 흔적을 찾아봐야 한다."}},"d":{},"ins":{}},"sq_hidden_bazaar_1/3":{"e":{"4":{"old":"f5280a9caaf26330a898a97bdbe5847a","t":"나는 십삼문 암시장으로 돌아가 여섯째의 장부를 다시 봐야겠다고 생각했다."},"2":{"old":"f1ef01a3af1ac09cd1a46fb2457dfe71","t":"나는 제 이름은 흑련회에 맡겨 두었으니 새길 수가 없었을 거라고 생각했다. 그래서 딸의 이름을 남겼나."}},"d":{},"ins":{}},"sq_hidden_bazaar_2/1":{"e":{"3":{"old":"b42ed512fd6a2b06285720631cb8a7c3","t":"월광 정수를 지어 주셔요. 기억을 흐리게 한다는 약이에요. 재료로는 만인장 무덤 틈의 요기 결정이 좋다더군요. 세 번쯤 캐 오셔요."}},"d":{},"ins":{}},"sq_hidden_bazaar_2/2":{"e":{"3":{"old":"5893e77f62ab9398157d74c5cd0a2d4a","t":"나는 서둘러 월광 정수를 지어 구슬에게 가져가기로 했다. 오래 쥐고 있을 물건은 아니다."}},"d":{},"ins":{}},"sq_hidden_bazaar_2/3":{"e":{"3":{"old":"82e1d1456b476cd10c9b8a9c0b65b3e0","t":"처음 여기 왔을 때 나는 그이한테 내 이름을 맡겼어요. 그런데 그 이름을 어디에 넘겼는지는 끝내 말해 주지 않았지요."}},"d":{},"ins":{"3":[{"s":"black_lotus:guseul","t":"그래도 나는 아직 사람이에요. 넘겨받은 누군가가 내 이름을 잘 간수하고 기억해 준다는 뜻이지요. 누군지 모르니, 불려도 대답은 못 하지만요."}]}},"sq_burial_steps_1/1":{"e":{"4":{"old":"200ea5392d2e6916d66c3f1086b9fa0c","t":"행렬 앞줄의 만인행군부터 두 번 끊으시오. 행렬은 머리를 잃으면 흩어지는 법이오."}},"d":{},"ins":{}},"sq_burial_steps_1/2":{"e":{"3":{"old":"676e595675e928a5b2c3bc99e57415b9","t":"그렇소. 그 영감은 남을 다 묻고 정작 자기는 묻어 줄 사람이 없었소. 관 곁을 지키는 백골 갑사 셋부터 치우시오."}},"d":{},"ins":{}},"sq_burial_steps_1/3":{"e":{"3":{"old":"e9d8719d0699ab10e4eb2b13cdfc93ac","t":"영감은 만장 묘지기가 되어 만장 사이 가장 깊은 곳에 있을 거요. 쓰러뜨려서, 이제 쉬라고 전해 주시오."}},"d":{},"ins":{}},"sq_burial_steps_2/1":{"e":{"2":{"old":"62643a3f5b193b02a9b022500d31860b","t":"혼자서는 다 못 닦아요. 비석에 앉는 원령재를 네 번쯤 걷어서, 세 줌만 저 주실래요?"},"1":{"old":"63af03a00e94c609f06761c5bb4b20d2","t":"재가 앉으면 이름이 지워져요. 이름이 지워지면 여기 누운 사람도 잊혀요. 그게 진짜로 죽는 거래요."}},"d":{},"ins":{}},"sq_burial_steps_2/2":{"e":{"2":{"old":"a669fa5fce5597b1f62c28a226ffae4b","t":"비석 까마귀들이 자꾸 와서 글자를 쪼아요. 두어 마리만 쫓아 주세요."},"3":{"old":"f5984593a0c651c14549a9dea9af4aa4","t":"나는 만인장에서 황지도 두 장 구해 오겠다고 했다. 탁본을 떠 두면 지워져도 남는다고."}},"d":{},"ins":{}},"sq_forgotten_city_1/1":{"e":{"4":{"old":"9666a4d54d71e0b55654609284aa2363","t":"성 안을 세 번쯤 살펴보시오. 종이 끌려간 자국이 보일 게요. 나는 더는 그 길을 걷지 못하겠소."},"1":{"old":"1641ddc9b602188867463240311a4e65","t":"그대가 종의 자취를 쫓는 조사원이구려. 그 종이 이 성을 지나갔소."}},"d":{},"ins":{}},"sq_forgotten_city_1/2":{"e":{"3":{"old":"7385a6c41a08740b88d7dfe0e8eb20ce","t":"나는 길을 막은 고도 결계관 둘을 걷어 내고, 관아 안의 흔적까지 읽어야겠다고 생각했다."}},"d":{},"ins":{}},"sq_forgotten_city_1/3":{"e":{"2":{"old":"9d04d70e198e8803a7d36acbe0c8c305","t":"나는 종이 지나간 뒤에 본부 사람 하나가 여기까지 따라왔었다고 짐작했다."},"3":{"old":"cbe6bec0f3c4e99614cd454ffb7ff207","t":"누가 왜 그랬는지는 아직 모른다. 다만 글씨를 지운 손은 조금도 서두르지 않았다. 나는 사관 여휘에게 돌아가 이 글씨를 알리기로 했다."},"1":{"old":"55c8313ac430aed74e9bae6adee64757","t":"이름은 없고 직함만 반쯤 남았다. 「야행국 본부」까지만 읽히고, 그 뒤는 누가 손끝으로 문질러 지웠다."}},"d":{},"ins":{}},"sq_forgotten_city_2/2":{"e":{"3":{"old":"e7cfd275eb58f9f0e54df863b3223fa0","t":"이렇게 남았사옵니다. 아무도 모르는 채로. 망국 근위장이 정전 문을 지키고 있사옵니다. 그를 넘지 않고는 폐하께 닿지 못하옵니다."}},"d":{},"ins":{}},"sq_under_root_1/1":{"e":{"4":{"old":"715bc83ccf5ed58c2145104b233a2cd1","t":"그걸 알려면 남은 응축 영핵부터 세 번 캐 봐야지. 영핵은 뿌리의 심장 소리를 기억하오."}},"d":{},"ins":{}},"sq_under_root_1/2":{"e":{"3":{"old":"b10907c32f9984794fbb4e332a32e685","t":"요기 결정 맥은 뿌리 지네들이 갉아먹고 있소. 두어 마리 치우고 결정을 세 번 캐 보시오. 캔 영핵 둘은 내게 맡기시고."}},"d":{},"ins":{}},"sq_under_root_1/3":{"e":{"2":{"old":"ea979896754379b4573c4a381e854d4e","t":"반석이 한동안 말이 없다가 내가 건넨 영핵 둘을 등잔 옆에 내려놓는다."},"1":{"old":"157ea99d99b8d6ef420277d3da3059cd","t":"나는 지도에서도 길이 끊긴, 가장 깊은 곳이라고 중얼거렸다."}},"d":{},"ins":{}},"sq_under_root_2/1":{"e":{"4":{"old":"222ae7e57517ce4cf79a62156c70ea54","t":"정화 부적 세 장을 지어 물에 띄워 주세요. 물은 덮어 주면 조용해져요."}},"d":{},"ins":{}},"sq_under_root_2/2":{"e":{"2":{"old":"6279918a51d18751019a5ff7d323039c","t":"나는 지하 수맥귀부터 정리하겠다고 했다."}},"d":{},"ins":{}},"sq_under_root_2/3":{"e":{"3":{"old":"2494dfdc9d057af32be6b94b20017d4e","t":"회생 부적 하나만 지어 와 주세요. 그 자리에서 다시 숨 쉬지 못하게 묻어 주는 거예요."}},"d":{},"ins":{}},"sq_black_tide_rift_1/1":{"e":{"4":{"old":"40fce78484531d2d4e27b51afc9ff73d","t":"낚싯대. 녀석이 늘 들고 다니던, 손잡이에 은가락지를 감은 놈이오. 손이 떨려서 혼자 줄을 못 당기겠으니, 세 번만 대신 낚아 올려 주시오."},"1":{"old":"368529ae6111658421691f698d684656","t":"내 아들 녀석이 남쪽 군도 등대지기였소. 몇 해 전 폭풍 치던 밤에 바다로 쓸려 들어갔지."}},"d":{},"ins":{}},"sq_black_tide_rift_1/2":{"e":{"3":{"old":"3f5e418d2814abf48ec87375db5c0484","t":"그런데 검은 물결 촉수 놈들이 자꾸 줄을 감아 가오. 녀석 것을 뺏으려는 것처럼. 두어 놈 떼어 내고 두 번만 더 던져 봐 주시오."}},"d":{},"ins":{}},"sq_black_tide_rift_2/2":{"e":{"2":{"old":"826b3c067920d988c494d0cc7202e73b","t":"저기, 물 위로 발이 보이지. 우리 애들이야. 서로 뒤엉켜 역천 표류체가 돼 버렸어. 둘만 먼저 풀어 줘."}},"d":{},"ins":{}},"sq_black_tide_rift_2/3":{"e":{"3":{"old":"973c74f0c956b6295ddc81523f314e29","t":"아직 셋 남았는데, 그 셋을 쥐고 있는 놈이 있어. 균열 한가운데, 배를 삼킨 그놈. 다들 균열을 삼킨 자라고 부르지."}},"d":{},"ins":{}},"sq_white_tower_1/1":{"e":{"1":{"old":"bbed56f0238c631c699940527e6dab46","t":"아, 왔네요. 부탁이 있어요. 별모래 좀 모아 줘요. 탑 난간에 쌓이는 성진사요. 세 번쯤 쓸어 담으면 돼요."}},"d":{},"ins":{}},"sq_white_tower_1/2":{"e":{"2":{"old":"4eda43b654bc1f34d2fa18f3fc317d81","t":"떨어진 별은 거울에 비쳐 보면 어디로 갔는지 알 수 있어요. 탑에 흩어진 귀경 파편을 두 조각만 주워 줘요."}},"d":{},"ins":{"2":[{"s":"mandate_court:seo","t":"파편 곁엔 별빛 나비 떼가 모여 있을 테니 두어 번 쫓아내고요. 성진사 두 줌은 나한테 줘요. 파편 위에 뿌려 볼 거예요."}]}},"sq_white_tower_1/3":{"e":{"0":{"old":"27c0b32c892ba785650532b9a9b28f5b","t":"서이연이 귀경 파편 위에 성진사를 뿌린다. 모래가 미끄러져 한쪽으로 모인다. 아래쪽으로."}},"d":{},"ins":{}},"sq_white_tower_2/2":{"e":{"3":{"old":"c8be209eb96c9f23dda82aa32d733d82","t":"나는 영핵을 돌려받으며, 이제 이걸로 천령 감로만 지으면 된다고 했다."}},"d":{},"ins":{}},"sq_star_observatory_1/2":{"e":{"0":{"old":"7fdbde37ef3652b41f33aa32ece6aaf6","t":"하나는 여기서 켜 두고, 하나는 제가 탑 지하에 미리 놓아 두겠습니다. 두 불이 같은 글을 비추면 거짓이 아닙니다."},"1":{"old":"99e6d1e4b8dca537df2d843a22d967c7","t":"백옥 천문탑에 가시거든 성도 앞을 세 번은 살피십시오. 글자는 불빛이 흔들릴 때만 보입니다."}},"d":{},"ins":{}},"sq_star_observatory_1/3":{"e":{"2":{"old":"3a7406193a8e5acc84435df8e32d6564","t":"천명원은 그 사람이 무엇을 하려는지 알고 있었다. 나는 숨을 삼켰다."}},"d":{},"ins":{"3":[{"s":null,"t":"나는 이 기록을 들고 무극 관성대의 문서진에게 돌아가기로 했다."}]}},"sq_star_observatory_2/1":{"e":{"2":{"old":"562d4a03dbf3d83cfaa3e8c590974bc1","t":"그분 곁의 천문 거울귀와 천문식자들이 탑을 오르는 사람을 막습니다. 저희는 감히 오르지 못했습니다."},"3":{"old":"ceb9705ec0e27fda9fffc5c17399426e","t":"백옥 천문탑 거울 계단의 천문 거울귀부터 셋쯤 걷어 내고 올라가 주십시오. 그분이 보신 것을 듣고 와 주셔야 합니다. 지금 태사령께서는 아무 말씀도 하지 않으시니까요."}},"d":{},"ins":{}},"sq_sealed_abyss_1/1":{"e":{"4":{"old":"8bb6ea04b1af037c71478e845e21aa77","t":"먼저 사슬을 갉는 심연 사슬귀부터 네 마리쯤 걷어 주십시오. 그러면 봉인이 어떻게 버티는지 보실 수 있습니다."}},"d":{},"ins":{}},"sq_sealed_abyss_1/2":{"e":{"3":{"old":"e147414729de8f332642bde72d63d874","t":"다시 감기는 데 걸리는 시간이 매번 조금씩 깁니다. 봉연 거울귀들이 그 틈을 비추고 있습니다. 둘만 깨 주십시오. 거울에 무엇이 비치는지 봐야겠습니다."}},"d":{},"ins":{}},"sq_sealed_abyss_2/1":{"e":{"2":{"old":"b091d84f063f246ef967ce2eb9b415d9","t":"구중 봉연에서 캔 응축 영핵은 그 아래 것의 숨을 품고 있을 거예요. 세 번쯤 캐 와 줘요."}},"d":{},"ins":{}},"sq_sealed_abyss_2/2":{"e":{"3":{"old":"4bb28d8d571167c81dd10b43843a1ec6","t":"나는 봉연을 두어 번 더 살피고 요기 결정도 세 번 캐 두기로 했다. 숨이 닿는 범위를 알아야 한다."}},"d":{},"ins":{}},"jq_artificer/1":{"e":{"3":{"old":"51a0669938af6e69fb7c77ee2b8b07ad","t":"자네가 앞에 서는 사람이라면 성벽의 녹슨 창귀 셋부터 상대해 보게. 맞으면서 버티는 법을 보여 주게."}},"d":{},"ins":{}},"jq_scout/1":{"e":{"3":{"old":"762d1af8bc166461e9cb49605840df99","t":"화살 두 묶음 깎아 와요. 그리고 과녁 쥐떼를 세 번 쏘세요. 과녁 대신."}},"d":{},"ins":{}},"jq_scout/2":{"e":{"1":{"old":"02798df2fe878f7979cfbf73ed511695","t":"쥐떼가 어디서 오는지 알아요? 잿빛 들녘의 버려진 초소에서요. 지난 순찰조가 거기서 돌아오지 않았어요."},"2":{"old":"6ed6ebdb8952951e9a333ca87f31df85","t":"들녘을 세 번쯤 뒤져서 흔적을 읽어 와요. 조사원은 발로 쓰는 사람이니까."}},"d":{},"ins":{}},"rq_old_prison/1":{"e":{"6":{"old":"c934334335d7efff7cbebd84073e8dba","t":"나 혼자서는 복도 끝까지 못 가오. 복도에 칼 쓴 옥귀들이 줄지어 섰거든. 좀 앞장서 주시겠소?"}},"d":{},"ins":{}},"rq_old_prison/3":{"e":{"2":{"old":"f26a4af68e913451529034c1866af2a5","t":"마춘이 황지를 받아 침을 묻혀 한 장씩 빗장에 붙인다. 손이 떨리지만 붙이는 자리는 정확하다."}},"d":{},"ins":{"6":[{"s":"q:r71_machun","t":"국문장의 형리 나리요. 죽어서도 형틀을 놓지 않는 의금부 형리귀. 그것까지 눕혀야 이 옥사가 조용해지오."}]}},"sq_forgotten_city_1/4":{"e":{"0":{"old":"232eed4b21267f595653e7aa2403d420","t":"야행국 본부라. 내 젊을 적에도 본부 사람이 이런 데까지 내려온 일은 없었소."},"1":{"old":"29035a2e515114cff8bf5953a61c8da0","t":"이름을 빼앗긴 자는 울며 오지. 그런데 그자는 울지도 않고 왔다가 말없이 갔소. 그게 마음에 걸리오."},"2":{"old":"e268b369e5d336707d1e17a66f7ec736","t":"여휘가 빈 책장 맨 끝에 「야행국 본부」까지만 적는다. 붓끝이 처음으로 떨리지 않는다."},"3":{"old":"08a2da5276868a0242e68c3bf3487b62","t":"이 줄의 나머지는 언젠가 그대가 채워 오시오. 먼 데보다 가까운 데를 잘 살피시고."}},"d":{},"ins":{}},"sq_jade_pass_1/2":{"e":{},"d":{},"ins":{"4":[{"s":null,"t":"나는 캔 약초를 호송대장에게 가져가자고 했다."}]}},"sq_frost_valley_1/2":{"e":{},"d":{},"ins":{"4":[{"s":"q:rn_seolbaek","t":"캔 빙정염은 제게 넘겨 주십시오. 인장 둘레에 뿌려 다지겠습니다."}]}},"sq_frost_valley_2/1":{"e":{},"d":{},"ins":{"3":[{"s":"q:rn_seolbaek","t":"빙혼 장수 곁엔 늘 빙벽 갑귀들이 붙어 다닙니다. 갑귀 둘을 먼저 치워야 장수에게 닿을 수 있어요."}]}},"sq_forgotten_city_2/1":{"e":{},"d":{},"ins":{"4":[{"s":null,"t":"나는 폐하를 직접 뵙겠다고 했다."},{"s":"q:bl_damu","t":"정전으로 가시려면 석상 수문병들을 지나셔야 하옵니다. 셋쯤 무너뜨리셔야 길이 나지요."}]}},"sq_black_tide_rift_2/1":{"e":{},"d":{},"ins":{"4":[{"s":"q:bl_chaeun","t":"갑판 잔해엔 검은 게 떼가 들끓어. 그것부터 세 번쯤 치워 줘. 애들한테 가는 길이야."}]}},"sq_white_tower_2/1":{"e":{},"d":{},"ins":{"4":[{"s":"q:bl_galhyeon","t":"감로의 바탕은 응축 영핵이오. 영핵부터 하나 지어 보여 주시오. 결이 고와야 감로가 맑소."}]}},"sq_star_observatory_2/2":{"e":{},"d":{},"ins":{"2":[{"s":null,"t":"위층에서 셈하는 천문식자들을 지나야 꼭대기에 닿을 수 있다. 나는 계단을 더 올랐다."}]}},"sq_star_observatory_2/3":{"e":{},"d":{},"ins":{"2":[{"s":null,"t":"나는 꼭대기 문 앞에 섰다. 목소리의 주인은 이미 탑 꼭대기 원령이 되어 있을 것이다."}]}},"sq_star_observatory_2/4":{"e":{},"d":{},"ins":{"1":[{"s":null,"t":"나는 무극 관성대로 내려가 운해에게 그 말을 전했다."}]}},"sq_sealed_abyss_1/3":{"e":{},"d":{},"ins":{"3":[{"s":"q:bl_jaeum","t":"사슬을 가장 많이 끊는 놈이 따로 있습니다. 사슬 끊는 자. 그놈을 쓰러뜨려 주시면 끊기는 간격을 셀 수 있을 겁니다."}]}},"sq_sealed_abyss_2/3":{"e":{},"d":{},"ins":{"2":[{"s":null,"t":"나는 영핵 둘을 챙겨 무극 관성대의 서이연에게 서둘러 돌아가기로 했다."}]}},"jq_artificer/2":{"e":{},"d":{},"ins":{"2":[{"s":"q:dh_daegeun","t":"돌아올 땐 장비 수리 도구도 하나 지어 오게. 이 녹슨 창도 손볼 때가 됐어."}]}},"rq_old_prison/2":{"e":{},"d":{},"ins":{"6":[{"s":"q:r71_machun","t":"감방 안쪽엔 빙의된 죄수들이 부적을 뜯고 있소. 두엇만 눌러 주시고, 황지 석 장만 구해 주시오. 뜯긴 자리에 새로 붙여야 하니."}]}},"jq_exorcist/1":{"e":{"3":{"old":"d7953a0159573c9d30912f28fa0fd68c","t":"제 방울은 방울먹는 무녀귀가 삼켰어요. 촛농 도깨비불들이 그 언니 앞을 지켜요."},"4":{"old":"5c35d5a805d5418c535374383c783cb8","t":"퇴마관님은 이름을 부를 수 있잖아요. 촛농 도깨비불부터 세 번만 흩어 줘요. 이름을 불러 주면 걔들도 길을 비킬 거예요."}},"d":{},"ins":{}},"jq_exorcist/3":{"e":{"2":{"old":"86747db29f9346a5d1e65547791ea307","t":"나는 거둬 온 부적실로 방울을 다시 매어 주었다."}},"d":{},"ins":{"-1":[{"s":null,"t":"쓰러지기 직전, 무녀귀가 아주 잠깐 고개를 돌렸다. 불러 준 옛 이름에 돌아보듯이."}]}},"jq_medic/1":{"e":{"1":{"old":"b743a4327b7191eca1e6e0453a4acdf4","t":"의무관이지? 손을 보면 알아. 약 냄새가 배어 있거든."}},"d":{},"ins":{"3":[{"s":"q:dh_gopun","t":"잿빛 들녘에 가서 야령초 네 줌이랑 약제 바탕 두 번을 거둬 와. 야령초는 내가 달일 테니 넘기고, 약제 바탕은 자네가 챙겨 둬. 곧 쓸 데가 있어."}]}},"jq_medic/2":{"e":{"1":{"old":"531717eb6e1dc300a7bf53484086dbb9","t":"이제 청심환 두 알만 지어서 가져와. 의무관이면 처방은 알 거고. 남은 사람들한테 먼저 돌릴 거야."}},"d":{},"ins":{}},"rq_seal_vault/4":{"e":{"5":{"old":"2004a67fc23fe82302b1882b8a4c36d0","t":"이제 목록도 천이백하나요. 내일 밤에 세면 처음으로 셈이 맞을 것이오."}},"d":{},"ins":{}},"rq_tide_gate/1":{"e":{"6":{"old":"1545cf601f36aa38a69f499a95aba2ef","t":"물에 젖어도 안 썩는 나무랑 축에 바를 비늘 기름이 있어야 하우. 기름부터 하지. 갑문에서 물고기 두 마리만 낚고, 물가에 떨어진 수귀 비늘 세 개를 주워 오시우."}},"d":{},"ins":{}},"rq_tide_gate/2":{"e":{"2":{"old":"f3864812b8072a8f8a6bbbdad8440903","t":"조막심이 물고기 배를 갈라 기름을 짜고, 수귀 비늘을 갈아 섞는다. 비린내가 진동한다."}},"d":{},"ins":{"5":[{"s":"q:r71_jomaksim","t":"기름은 됐수. 이제 축에 덧댈 가공 부적목 두 개만 구해다 주시우. 그리고 도르래 탑 사슬에 붙은 도르래 집게들 좀 떼어 내 줘. 세 놈은 넘을 거유."}]}},"jq_sealmaster/1":{"e":{"2":{"old":"3b734f8c5a41b68cd2f358a3c7b4aeb7","t":"폐쇄 사당에 황지가 아직 남아 있을 겁니다. 세 번쯤 거두시면 넉넉할 겁니다. 다만 금줄식귀가 지키고 있으니 두 놈은 치우셔야 할 겁니다."}},"d":{},"ins":{}},"jq_sealmaster/2":{"e":{"0":{"old":"c5b75e081925ad52b614779ebd97dc3b","t":"황지도 넉넉하고, 금줄식귀까지 두 놈이나요. 대단하십니다."},"2":{"old":"65f1ea7134402ae231ca897eb83588a2","t":"거두신 황지로 정화 부적 두 장만 만들어 주시면 출납을 맞출 수 있습니다."},"1":{"old":"7aa62f9e8cd6c8e5c65ae16eefe12596","t":"그 금줄, 요즘 들어 자꾸 풀린다더군요. …아닙니다. 장부만 보다 보니 별게 다 마음에 걸립니다."}},"d":{},"ins":{}},"rq_crimson_altar/1":{"e":{"6":{"old":"b368d835809455b4a9547e6a92ef512a","t":"돌기둥 사이에 선 제물 원령들을 흩어 주세요. 네 번쯤이면 줄이 끊길 거예요. 기다릴 것은 아무것도 없다고 알려 줘요."}},"d":{},"ins":{}},"rq_crimson_altar/3":{"e":{"0":{"old":"5616c586e1a43905f383b8ad58fbebb9","t":"제단 둘레의 붉은 모래를 걷어 내자 그 밑에서 주사 광물이 드러난다. 손에 묻은 가루가 피처럼 붉다."},"3":{"old":"521a1b1ae2ab30ce53e59e3ec384f6b3","t":"경문을 거꾸로 외우면 의식이 풀린다고, 동생이 몰래 가르쳐 줬어요. 그 애는 끝까지 교단을 믿지 않았나 봐요."},"5":{"old":"341fb7c51b06b57c332a8fb09b65f49c","t":"월식 제사장귀예요. 그를 쓰러뜨려야 의식이 끝나요. 그러지 않으면 동생은 영영 그 줄에서 내려오지 못해요."}},"d":{},"ins":{}},"jq_analyst/1":{"e":{"3":{"old":"cd618322f487d991a6cf3f1f61bb6d95","t":"백지교에서 정제 황지를, 연무장에서 부적목을 세 번씩 거둬 와. 둘씩은 나한테 넘기고."}},"d":{},"ins":{}},"jq_analyst/2":{"e":{"0":{"old":"fc136b1cd2f31ee9ba65b598b72651ea","t":"황지 결이 곱네. 부적목도 마른 걸로 골랐고."},"1":{"old":"ea99e27c9dbd3bab792c607663a8124a","t":"뼈대는 쇠로 잡는다. 월철 주괴 두 개를 만들어서 가져와. 장비 수리 도구도 하나 만들어 두고. 등은 해마다 손봐야 하거든."}},"d":{},"ins":{}},"aq_headquarters/1":{"e":{"2":{"old":"3153b8e05e1125a82e9e700b30ede86c","t":"구름나루 주모 달래 님한테 이 보급 장부를 전해 주세요. 돌아오시면 노정 건량 세 개만 부탁해요. 숙직 들어가는 분들 몫이에요."}},"d":{},"ins":{}},"aq_headquarters/2":{"e":{"2":{"old":"cb258ba4338ed7737f6552aba5e35cfa","t":"건량 만들 거면 나루 쌀 좀 가져가. 정청 쌀보다 낫다니까. 노정 건량 세 개면 숙직 몫은 되겠지."}},"d":{},"ins":{}},"aq_fieldbureau/2":{"e":{"1":{"old":"01cdc0fc3cfe9c2d2167fa44cb5511a6","t":"길을 다시 묶으려면 약제 바탕이랑 부적목 수지가 두 번씩 필요해요. 이 대숲에서 거둘 수 있어요. 수지는 제가 표식에 바를게요. 그러면 요괴가 안 건드려요."}},"d":{},"ins":{}},"aq_archivebureau/1":{"e":{"2":{"old":"5701721dc19c0db3e1b91ad4ee22249f","t":"서고 벼루 곁에 먹정이 굴러다니네. 우리는 먹돌이라 부르지. 두 개만 거둬 오고, 책벌레 요괴도 두 마리쯤 치워 주게. 놈들이 먹정까지 갉아먹거든."}},"d":{},"ins":{}},"aq_archivebureau/2":{"e":{"0":{"old":"1faeb0db5599d9462dcf102f8cbdc485","t":"먹정이 좋군. 이걸 갈면 비교할 수 있어."},"1":{"old":"4b872f0cda8317d68b45ecc04b88d23d","t":"그런데 탈명 죽간이 또 깨어났다네. 남의 이름을 먹는 놈이지. 서고를 두어 번 뒤져 놈을 찾아내 쓰러뜨려 주게. 기록 지키는 사람이 그걸 두고 볼 순 없지."}},"d":{},"ins":{}},"rq_lamp_alley/1":{"e":{"2":{"old":"8e93df8c1c82ae6f52ba54bdd1f6dee2","t":"구경만 할 거면 저리 비키쇼. 등잔 하나 안 사고 구경만 하는 손님이 제일 반갑잖은 법이니까."}},"d":{},"ins":{"6":[{"s":"q:r71_soetdae","t":"그러니 부탁 좀 하오. 기름 창고에 들끓는 기름 쥐 떼부터 네 번만 쫓아 주쇼."}]}},"rq_lamp_alley/3":{"e":{"2":{"old":"df5315126735eff33b0660bb87065987","t":"쇳대가 영사를 받아 등잔 갓에 씌운다. 불빛이 부드럽게 퍼지며 골목 구석까지 닿는다."},"3":{"old":"84bc0ca22ea18fa02ac3d7ae7fd404b9","t":"영사로 갓을 씌우면 그늘이 줄어들지. 그늘이 없으면 놈들도 숨을 데가 없고."}},"d":{},"ins":{"5":[{"s":"q:r71_soetdae","t":"이제 두꺼비 차례요. 막다른 하수구에 등잔골 두꺼비 두목이 굴을 파고 있소. 그놈만 치우면 골목이 숨을 쉬오."}]}},"rq_star_hill/3":{"e":{"0":{"old":"173f223f019c26e5e7a2ba10916269aa","t":"반딧불 고인 웅덩이 가에 하얀 운면이 피어 있다. 그 사이에 종이 한 장이 걸려 있다."},"1":{"old":"a5bf4cc4da488ce079ff827236678317","t":"운면을 걷어 내자 종이가 드러난다. 별 하나만 그려져 있고, 그 별에서 가는 선이 언덕 아래로 이어진다."}},"d":{},"ins":{"5":[{"s":"q:r71_byeori","t":"돌의자예요! 오늘 밤 거기서 같이 봐요. 그 별이 정말 있는지."}]}},"rq_water_clock/1":{"e":{"5":{"old":"a8d830972497dcc1a73b891eda9e4f40","t":"물 받는 홈에 댈 영유리를 두 번만 거둬 주세요. 마른 수로 바닥에 박혀 있어요. 그리고 톱니에 덧댈 생 월철 세 개가 필요해요."}},"d":{},"ins":{}},"rq_water_clock/2":{"e":{"2":{"old":"7e462795db99fc8911413d5a3c573e8d","t":"누리가 생 월철을 받아 톱니 빠진 자리에 대고 망치질을 한다. 소리가 누각에 울려 시보처럼 들린다."}},"d":{},"ins":{"5":[{"s":"q:r71_nuri","t":"누각의 나무 인형들이 제멋대로 종을 쳐서 결계를 쳐요. 종 치는 인형귀를 세 번만 멈춰 주세요. 그래야 심장까지 갈 수 있어요."}]}},"aq_sealbureau/1":{"e":{"3":{"old":"0fd67c6a88e4db2ae6e870b1ebec71d4","t":"나는 봉인관리국에서 왔다고 밝히고, 폐수로를 두어 번 살펴보겠다고 했다."}},"d":{},"ins":{"3":[{"s":"q:dh_suchil","t":"뱃사공… 그림자 뱃사공들이 밤마다 와. 둘이야, 늘 둘. 걔들 좀 쫓아 줘."}]}},"aq_sealbureau/3":{"e":{"0":{"old":"01cb6e4b593123dfc022843f4852f5e6","t":"수문아귀가 물 밑으로 가라앉는다. 새로 만든 정화 부적을 기둥에 붙이자 검은 물빛이 조금씩 맑아진다."}},"d":{},"ins":{}},"aq_medicalbureau/2":{"e":{"1":{"old":"11266f1a15dd919ad812f7f766f9cd54","t":"연화원에서 약제 바탕이랑 월광 이끼를 두 번씩 거둬 주세요. 약제 바탕은 흙에 섞을 거라 저한테 주시고요. 그래야 연화원 흙 맛이 나요."}},"d":{},"ins":{}},"aq_independent/1":{"e":{"3":{"old":"2488fae90aaafa15f2cf66832616b2a7","t":"나루 물에서 뭐가 올라오는지 세 마리만 낚아 봐. 주모 눈엔 물고기 비린내가 제일 정직하거든."}},"d":{},"ins":{}},"aq_independent/2":{"e":{"2":{"old":"b05092696d6262384fd5b484be7f2644","t":"낚은 걸로 손질한 생선 두 접시만 만들어 줘. 그 손님들 상에 내면서 슬쩍 물어볼 게 있어."}},"d":{},"ins":{}},"rq_comet_crater/1":{"e":{"5":{"old":"848dc0122d54fe6a34a4b774af24d8ed","t":"나는 왜 아무도 피하라고 하지 않았는지 물었다."},"6":{"old":"e5c1451975da2562e219de02b311cf45","t":"그걸 알고 싶어서 여기 있어요. 분화구에 성진사가 고여 있어요. 혜성 꼬리가 식으며 떨어진 별모래죠. 두 번만 거둬 와 줄래요? 모래 결을 보면 혜성 심의 별쇠가 무엇을 품었는지 짐작할 수 있어요."}},"d":{},"ins":{}},"rq_comet_crater/2":{"e":{"1":{"old":"cf5ee762a34b5b4d4609402d47a947f5","t":"성진사네요. 우리끼리는 별모래라고 불러요. 이걸 체로 거르면 별쇠 결이 보여요."}},"d":{},"ins":{"5":[{"s":"q:r71_seoharam","t":"하늘 깃 매예요. 혜성과 함께 나타난 놈들이죠. 세 마리쯤 떨어뜨리고 천공 깃털 두 개만 가져다줘요. 깃털도 같은 쪽을 가리키는지 보고 싶어요."}]}},"rq_cloud_corridor/4":{"e":{"2":{"old":"39b6923c9884c95bddd4b05fe6205789","t":"…보이오. 흐리지만 보이오. 저기, 견우성이로구먼."}},"d":{},"ins":{}},"hs_byeolchae/2":{"e":{"3":{"old":"2c40d787c3a340742a5c15887020c1cc","t":"이제 수리비 천 전만 치르면 열쇠를 넘겨 드리지."},"0":{"old":"d01e06db6c8ac47a216d5ed4ab60f6bd","t":"순덕이 부적목을 하나씩 두드려 보고 고개를 끄덕인다."}},"d":{},"ins":{}},"fq_sealed_lord/1":{"e":{"4":{"old":"f53ddf0ce590c000800156edcba3ab67","t":"구중 봉주와의 결전에는 혼자 가셔도, 동료와 함께 가셔도 됩니다. 다만 넷을 넘으면 사슬이 버티지 못합니다."}},"d":{},"ins":{}},"gq_1/2":{"e":{"5":{"old":"5a9b3128b75b15feba4471c0116f61c0","t":"여울이 일렀나 보군. 그것들 비늘을 가져왔다고? 지붕을 이을 게 모자랐네."}},"d":{},"ins":{"7":[{"s":"q:g_mukho","t":"여울이 마을 끝 화로 곁에서 기다릴 걸세. 밤이 깊거든 가 보게."}],"3":[{"s":"q:g_mukho","t":"그래서 여기선 이름을 하나 더 지어 문패에 같이 적어 두네. 위는 바깥에서 받은 이름, 아래는 이 섬에서 지은 이름. 바깥 이름이 다 번져도 아래 이름으로 불리면 사람으로 남을 수 있거든."}]}},"gq_1/3":{"e":{"6":{"old":"0643db2a5d3cc39b84575069d588f255","t":"…오늘은 여기까지 하자. 객방에 자리 펴 뒀어. 내일은 잿빛 갈대숲에 가 봐. 이름을 부르는 소리가 들리면 대답하지 말고."}},"d":{},"ins":{"3":[{"s":"q:g_yeoul","t":"여기선 그런 사람을 반요라고 불러. 요기가 명줄을 갉으면 처음엔 제 이름이 남의 이름처럼 들리고, 나중엔 누가 불러 줘야 잠깐 돌아와. 다 끊기면 요괴고."}]}},"gq_2/3":{"e":{"2":{"old":"90fa583c53d31346cf9b8974fea08cf0","t":"흩어지는 사공의 윤곽 사이로 노 한 자루가 물에 떨어진다. 노에는 칼로 새긴 글자 두 개가 있다. 「한결」."},"3":{"old":"56a1df43b6f9d4712a2cf859b8933136","t":"나는 그것이 당신 이름이냐고 물었다."},"5":{"old":"4e5038fa8fc9c95e4f30c1caf72dcc25","t":"(뒤에서) …그 사공, 우리 배도 몰았어. 누가 이름을 불러 줬으니, 이제야 쉬네."}},"d":{},"ins":{}},"gq_5/1":{"e":{"3":{"old":"6ae2da639d26bd04c411569a21c0f04e","t":"왕좌 앞에 귀허의 문지기가 있어. 거울 몸이라 때리면 되튕겨. 그걸 넘어야 왕좌 앞에 설 수 있어."}},"d":{},"ins":{}},"jq_sealmaster/3":{"e":{"0":{"old":"0816eb83666432c91a591b0ab558d450","t":"윤도한이 부적을 받아 장부에 한 줄을 적는다. 셈이 맞자 그제야 어깨가 조금 풀린다."}},"d":{},"ins":{}},"aq_archivebureau/3":{"e":{"2":{"old":"7eb8c179f7ad958ba42af2f715ad2342","t":"먹은… 같은 먹이었네. 정청 안에서 쓰는 먹이야. 이건 아직 아무에게도 말하지 말게."}},"d":{},"ins":{"1":[{"s":"night_office:mo","t":"해마다 오래된 쪽을 거두는 것도 우리 일이지만, 되돌려 적는 쪽이 훨씬 기분 좋네."}]}},"hs_byeolchae/3":{"e":{"0":{"old":"a7ddfb960ecb003295a25a708222f2e1","t":"순덕이 허리춤에서 녹슨 열쇠 꾸러미를 풀어 하나를 골라낸다."}},"d":{},"ins":{}},"gq_3/3":{"e":{"5":{"old":"79d8c1c6869e8fb7389a9b33460b6ac0","t":"종이 바로 섰으니 이제 바른 기도가 되겠구려. 아이야, 어미의 이름을 불러 보아라. 불러 주는 이가 있는 한 이름은 흩어지지 않는다오."}},"d":{},"ins":{}},"jq_exorcist/2":{"e":{},"d":{},"ins":{"2":[{"s":"q:dh_gaeul","t":"언니를 재우면 제 방울이 나올 거예요. 끈이 삭았을 테니, 사당에서 부적실 두 타래만 거둬 와 주세요."}]}},"rq_seal_vault/1":{"e":{},"d":{},"ins":{"6":[{"s":"q:r71_hayunjae","t":"먼저 저주 인형 창고의 저주 인형 무리를 세 번만 눌러 주시오. 놈들이 깨어 있으면 서가에 다가갈 수가 없소."},{"s":"q:r71_hayunjae","t":"그리고 봉인고 바닥에 떨어진 결계 파편을 세 개 거둬 주시오. 끊긴 봉인이 있다면 파편이 그 자리를 알려 줄 것이오."}]}},"rq_seal_vault/2":{"e":{},"d":{},"ins":{"5":[{"s":"q:r71_hayunjae","t":"거울 창고에서 울음소리가 난 지 오래요. 울음 새는 거울을 두 번 깨뜨려 주시오. 오래된 일은 거울이 기억하고 있을지도 모르오."}]}},"rq_seal_vault/3":{"e":{},"d":{},"ins":{"5":[{"s":"q:r71_hayunjae","t":"바닥이 갈라진 깊은 창고에 아직 열지 않은 함이 하나 있소. 거기 든 것이 봉인고의 첫 압수물일 것이오. 함께 가 주시오."}]}},"rq_tide_gate/3":{"e":{},"d":{},"ins":{"5":[{"s":"q:r71_jomaksim","t":"큰 만조 때면 수문 날개 위에 만조의 수문귀가 올라선다우. 물이 차오르면 그놈을 맡아 주시우. 나는 도르래를 돌릴 테니."}]}},"rq_crimson_altar/2":{"e":{},"d":{},"ins":{"5":[{"s":"q:r71_somae","t":"제단 둘레 붉은 모래 밑에 주사 광물이 묻혀 있어요. 교단에서는 진사라고 불렀죠. 세 덩이만 캐다 주세요. 이번엔 의식을 거꾸로 돌릴 거예요."}]}},"rq_ember_pass/1":{"e":{},"d":{},"ins":{"6":[{"s":"q:r71_arang","t":"봉화에 밑불을 깔려면 숯이 있어야 해요. 고개 아래 숯 굽는 골에서 정련 숯을 네 번만 거둬 와 줄래요?"}]}},"rq_ember_pass/2":{"e":{},"d":{},"ins":{"5":[{"s":"q:r71_arang","t":"숯은 됐어요. 그런데 봉화대로 오르는 길에 불티 도깨비들이 들끓어요. 불씨 항아리를 노리니까 세 번쯤 쫓아 줘요."}]}},"rq_ember_pass/3":{"e":{},"d":{},"ins":{"5":[{"s":"q:r71_arang","t":"봉화대엔 아직 꺼진 봉화의 수호귀가 서 있대요. 그가 쉬어야 불을 옮길 수 있어요. 같이 올라가 줘요."}]}},"rq_snow_hollow/1":{"e":{},"d":{},"ins":{"6":[{"s":"q:r71_gombae","t":"골짜기 눈밭에 서리 족제비가 숨어 있어. 세 마리쯤 잡고, 바닥에 댈 요수 가죽 두 장만 갖다주게."}]}},"rq_snow_hollow/2":{"e":{},"d":{},"ins":{"5":[{"s":"q:r71_gombae","t":"이제 끈이야. 자작나무 밑동에 월광 이끼가 끼어 있을 거야. 우린 달이끼라고 부르지. 세 줌만 거둬 오게."}]}},"rq_snow_hollow/3":{"e":{},"d":{},"ins":{"5":[{"s":"q:r71_gombae","t":"이제 엮기만 하면 돼. 하룻밤 걸리니 다 되면 사냥막으로 다시 오게."}]}},"aq_fieldbureau/1":{"e":{},"d":{},"ins":{"2":[{"s":"q:dh_cheongun","t":"순찰로를 두어 번 살펴봐 주세요. 표식이 다 없어졌는데, 대나무 원숭이 짓 같아요. 놈들도 세 마리쯤 쫓아 주시고요."}]}},"rq_lamp_alley/2":{"e":{},"d":{},"ins":{"5":[{"s":"q:r71_soetdae","t":"헌데 두꺼비 심부름꾼들이 또 올 거요. 등잔 그늘 소매치기귀 말이오. 두 놈만 혼내 주고, 오는 길에 영사 한 필만 구해다 주쇼. 쓸 데가 있소."}]}},"rq_star_hill/1":{"e":{},"d":{},"ins":{"6":[{"s":"q:r71_byeori","t":"은하수 보이는 마루 쪽 고목에 부엉이들이 살아요. 성도 물어 가는 부엉이요. 세 마리쯤 쫓으면 둥지에서 종이를 찾을 수 있을 거예요."}]}},"rq_star_hill/2":{"e":{},"d":{},"ins":{"5":[{"s":"q:r71_byeori","t":"반딧불 고인 웅덩이 가에 운면이 잔뜩 피어 있어요. 구름솜처럼 생긴 거요. 종이가 거기 걸렸을지도 몰라요. 두 번만 걷어 봐 주세요."}]}},"rq_water_clock/3":{"e":{},"d":{},"ins":{"5":[{"s":"q:r71_nuri","t":"심장은 물시계 태엽 거인 가슴에 있어요. 그가 길을 막고 있어요. 쓰러뜨려 주면 제가 열쇠를 꽂을게요."}]}},"aq_sealbureau/2":{"e":{},"d":{},"ins":{"2":[{"s":null,"t":"나는 수문아귀를 쓰러뜨리고, 정화 부적을 새로 만들어 기둥에 붙이겠다고 했다."}]}},"aq_medicalbureau/1":{"e":{},"d":{},"ins":{"2":[{"s":"q:dh_seonhwa","t":"덩굴 손을 세 번쯤 쳐 주시고, 연화원 둘레를 두어 번 살펴봐 주세요. 어디로 넘어오는지 알아야 막죠."}]}},"rq_comet_crater/3":{"e":{},"d":{},"ins":{"6":[{"s":"q:r71_seoharam","t":"저기가 혜성 심이에요. 혜성 심의 파수꾼이 지키고 있어요. 그걸 넘어야 별쇠를 볼 수 있어요."}]}},"rq_cloud_corridor/1":{"e":{},"d":{},"ins":{"6":[{"s":"q:r71_undam","t":"헌데 회랑 마디마다 난간 바람귀가 들끓소. 네 번쯤 흩어 주면 내가 길을 더듬어 가 보겠소."}]}},"rq_cloud_corridor/2":{"e":{},"d":{},"ins":{"5":[{"s":"q:r71_undam","t":"망대 가는 처마 위에 번개 머금은 학 두 마리가 맴도오. 소리로 알지. 그놈들을 떨어뜨려 주시오."}]}},"rq_cloud_corridor/3":{"e":{},"d":{},"ins":{"5":[{"s":"q:r71_undam","t":"망대에 닿으면 회랑 끝의 천문 거울이 덤벼들 것이오. 오래 땅만 본 거울이라 성이 나 있소. 한 번 꺾어 놓아야 하늘로 돌릴 수 있소."}]}},"hs_byeolchae/1":{"e":{},"d":{},"ins":{"3":[{"s":"q:hs_bomi","t":"들보 고칠 부적목 여섯 개, 문창에 바를 황지 네 장을 거둬다 주시우. 처음 깔 오방색 방석 하나는 손수 만들어 오고."}]}},"gq_1/1":{"e":{},"d":{},"ins":{"8":[{"s":"q:g_yeoul","t":"그 전에 하나만. 촌장님은 요즘 지붕 이을 비늘이 모자라 걱정이셔. 잿빛 갈대숲에서 갈대 물귀신을 세 번쯤 쓰러뜨리고 반요 비늘 두 개를 가져가면 반가워하실 거야."}]}},"gq_2/1":{"e":{},"d":{},"ins":{"6":[{"s":"q:g_sagong","t":"말뚝은 갈대숲 곳곳에 박혀 있소. 네 군데는 뒤져야 할 거요. 갈대 영사 세 타래로 물살을 거르면 잠긴 글자가 떠오를 거요."}]}},"gq_2/2":{"e":{},"d":{},"ins":{"5":[{"s":"q:g_sagong","t":"…이제 생각나는구려. 건너편은 없소. 나를 놓아주시오. 이 노를 쥔 손을 쳐서 떨어뜨려 주시오."}]}},"gq_3/1":{"e":{},"d":{},"ins":{"7":[{"s":"q:g_dani","t":"향을 바로 세우면 기도도 바로 된대요. 근데 거꾸로 향목은 매달린 동자들 밑에 떨어져 있어요. 거꾸로 매달린 동자들 좀 세 번만 쫓아 주시고, 향목 세 개만 주워 주세요."}]}},"gq_3/2":{"e":{},"d":{},"ins":{"6":[{"s":"q:g_juji","t":"범종이 아직 거꾸로 울고 있소. 거꾸로 선 범종귀를 잠재우면 이 사당의 기도가 바로 설 것이오."}]}},"gq_4/1":{"e":{},"d":{},"ins":{"5":[{"s":"q:g_yeoul","t":"…저 끝 좌판의 기억 저울 장수가 이 거리 기억을 다 쥐고 있어. 쓰러뜨리면 기억이 망각 수정으로 굴러떨어질 거야. 세 개만 주워 와. 장부 얘기는 그다음에 할게."}]}},"gq_4/2":{"e":{},"d":{},"ins":{"6":[{"s":"q:g_yeoul","t":"그 전에 반요촌에 가자. 촌장님께 그 장부를 보여 드려. 망각 수정도 하나 가져가고. 그분 이름도 거기 있을 거야."}],"4":[{"s":"q:g_yeoul","t":"바깥 정청이 해마다 하는 명부 정리랑 같은 셈이야. 줄 하나 그으면 바깥에선 아무도 그 이름을 다시 안 불러."}]}},"gq_5/2":{"e":{},"d":{},"ins":{"8":[{"s":"q:g_yeoul","t":"…막아야 해. 반요촌 상점에서 귀허 부적을 지니고 와. 부적이 없으면 주인 앞에 설 수 없어. 혼자든, 동료와 넷까지든."}]}}}'::jsonb; ep jsonb := '{"mq_frost_seal":{"e":{"8":{"old":"178da7d02e0c9e892a3e9cd9759c6135","t":"윤 출납관, 언제 왔어요? …아니, 됐어요. 남쪽으로 가요."}},"d":{},"ins":{}},"mq_ash_sea":{"e":{"3":{"old":"fb25aad466488091c8458728ae2f1854","t":"꺼진 등대 여섯은 다시 켤 수 없어요. 문이 이미 열렸으니까. 그래도 남은 세 불은 제가 계속 돌아가며 지킬게요."}},"d":{},"ins":{}},"mq_drowned_ledger":{"e":{"5":{"old":"929052fdf3556239de962830285ade98","t":"값이 있으니 사 갔겠지요. 몸은 갔어도 장부에 이름이 남아 있으면 아직 영으로 남은 사람들이니까요. 장부에서는 모든 게 값이 있습니다."}},"d":{},"ins":{}},"mq_red_moon_oath":{"e":{"8":{"old":"a37c580452390182401373bcbd90616b","t":"아무도 대답하지 않는다. 한설이 장부 귀퉁이를 한 번 쓸어내릴 뿐이다."}},"d":{},"ins":{}},"mq_nine_gates":{"e":{"8":{"old":"240cfab452234f762abc37ae53e092f4","t":"출납관 윤도한. 구중 봉연, 아홉째 문 안쪽 근무. …지운 자리 없이 적어라. 올해 먹 거두기는 하지 않는다."},"10":{"old":"39de54edea9e1a656bdf77930ea252dc","t":"그 시각, 봉연 가장 깊은 곳. 닫힌 문 아래 어둠 속에서 구중 봉주가 천천히 숨을 고르고 있다. 문틈으로 스며드는 지워진 이름들을 하나씩 삼키며."}},"d":{},"ins":{}}}'::jsonb; sc jsonb := '{"night_office:join:1":{"e":{"4":{"old":"d77537262e9b7e21f2fdc91479dc3d9d","t":"기초 교육부터 받는다. 잿빛 들녘에 나가 세 번 탐색하고, 요괴 둘을 쓰러뜨려라. 본 것은 하나도 빼놓지 말고 적어서 정청으로 가져와라."}},"d":{},"ins":{}},"night_office:rank:2":{"e":{"0":{"old":"c8d763152a2ae2908472f3862da3c5fb","t":"지하서고는 두 번은 뒤져야 뭐가 나온다니까요. 어디 봐요, 먹 색이 다른 그 장부 맞죠?"}},"d":{},"ins":{"3":[{"s":"night_office:han","t":"다음 일이다. 야시장에 이름 없는 장부가 돈다. 평판이 팔백에 닿으면 그 길을 쫓아 길목의 요괴 다섯을 쓰러뜨리고, 탐색에서 단서 하나를 건져 와라."}]}},"night_office:rank:3":{"e":{"0":{"old":"2fa259ca73e475d1a4ea700f8e93cdfd","t":"요괴 다섯에 단서 하나. 산 사람도 판 사람도 입을 닫던 장부다. 그 길 끝에 무엇이 있었나."}},"d":{},"ins":{"3":[{"s":"night_office:han","t":"북령맹에서 얼음 인장에 금이 갔다는 기별이 왔다. 평판이 천육백에 닿으면 봉인 문서를 들고 철벽 고찰로 가라. 가는 길에 빙혼곡 원정을 끝까지 다녀와 금 간 자리도 살피고."}]}},"night_office:rank:4":{"e":{"0":{"old":"ff5dfb8445a54e3a97e1a6dc573c047f","t":"문서는 철벽 고찰에 잘 건넸고, 빙혼곡도 끝까지 살피고 왔다지. 수고했네."}},"d":{},"ins":{"2":[{"s":"night_office:baek","t":"평판이 삼천에 닿거든 정청으로 오게. 자네에게 줄 자리가 하나 남았네."}]}},"red_moon_cult:join:1":{"e":{"3":{"old":"ceaa515d4a10a1af3fb3cbe4d96d6241","t":"적사 황무지나 유리협곡, 흑사단 폐단 같은 적월 변경으로 나가 요괴 셋을 쓰러뜨리세요. 붉은 모래가 당신을 먹으려 들 거예요."}},"d":{},"ins":{"3":[{"s":"red_moon_cult:danbi","t":"침식이 스물 넘게 배어든 채로 이 붉은 등 아래로 돌아오세요. 먹히지 않고 돌아온다면 요기를 다룰 줄 안다는 뜻이에요."}]}},"red_moon_cult:join:2":{"e":{"1":{"old":"6d1b236f764308b3c7a7caa74afbf4c6","t":"흥. 요괴 셋을 베고 살아 돌아왔군. 대부분은 첫 모래바람을 못 넘긴다."}},"d":{},"ins":{"3":[{"s":"red_moon_cult:danbi","t":"오늘 밤 장터의 등불이 모두 꺼지면 이 붉은 등 아래로 다시 오세요. 교주님께서 입교 의식을 치러 주실 거예요."}]}},"red_moon_cult:rank:2":{"e":{"0":{"old":"cf3d18e386a0e9db8ddc5aada93c283a","t":"유리협곡 결정을 캐 왔네요. 이걸 곱게 갈아서 혈서 먹으로 써요."}},"d":{},"ins":{"2":[{"s":"red_moon_cult:sama","t":"다음은 흑사단 폐단이다. 한때 우리 형제였던 자리를 이름 없는 시체들이 지킨다. 평판이 팔백이 되면 가서 다섯을 베고 돌아와라."}]}},"red_moon_cult:rank:3":{"e":{"0":{"old":"d72b07c92d97c6c79773b665b156d9dc","t":"흑사단에서 다섯을 베고 돌아왔군. 한때 우리 형제였던 자리다."},"1":{"old":"2b5c8a0b8e4f544869f14966b6b1fb2b","t":"그들이 무엇을 바쳤는지 묻지 마라. 너는 그 자리를 지나 돌아왔다. 그거면 됐다."}},"d":{},"ins":{"3":[{"s":"red_moon_cult:sama","t":"평판이 천육백에 닿으면 적월교 월식성으로 가라. 교주님께서 보여 주실 것이 있다. 성 안을 세 번 살피고 오너라."}]}},"red_moon_cult:rank:5":{"e":{"0":{"old":"3051d3236d3cc1735cb581dfc9324149","t":"왔구나. 약속한 말을 해 주마."}},"d":{},"ins":{}},"river_alliance:join:1":{"e":{"2":{"old":"d2c72f40a53b738d41afa34013f1c9cb","t":"내가 서 주마. 대신 부탁 하나 들어줘. 염등촌에 댈 물건이 모자라거든. 어디서든 세 번 채집해서 물건을 모으고, 하나는 안전지대 상점에 팔아 봐."}},"d":{},"ins":{"2":[{"s":"river_alliance:nodeul","t":"값을 제대로 매기는 놈인지 보려는 거야. 다 되면 이 나루로 와. 매향이가 장부를 보고 셈해 줄 거다."}]}},"river_alliance:rank:2":{"e":{"0":{"old":"2eb9a388b35fb965084dc4d88eba357d","t":"염등촌에 기름감을 대 주셨다고요. 마을에서 벌써 고맙다는 기별이 왔어요."}},"d":{},"ins":{"2":[{"s":"river_alliance:nodeul","t":"수경루 물시계가 거꾸로 흐른다는 소문이 돌아. 평판 팔백쯤 되면 가서 두 번만 살펴봐. 물길이 뒤집히면 배도 뒤집히거든."}]}},"river_alliance:rank:3":{"e":{"0":{"old":"1008f05b8e3541b847fae9e30bd8416c","t":"수경루에 다녀왔나. 그래, 물시계가 정말 거꾸로 흐르던가?"}},"d":{},"ins":{"2":[{"s":"river_alliance:jin","t":"전쟁이 나면 제일 먼저 끊기는 게 뱃길이에요. 평판이 천육백이 되면 서로 다른 안전지대 세 곳에 들러 연맹 깃발을 걸고, 거래소에서 한 번 사고팔아 장부를 돌려 주세요."}]}},"river_alliance:rank:4":{"e":{"0":{"old":"cc2738446c42022673f87d1b9561ae38","t":"뱃길을 붙잡아 두셨네요. 거래소 장부도 막힘없이 돌았고요."}},"d":{},"ins":{"2":[{"s":"river_alliance:jin","t":"평판이 삼천이 되면 용잠 수궁 원정을 끝까지 다녀와 주세요. 수궁 깊은 곳에서 노래가 들린대요. 그 노래가 무엇을 부르는지, 연맹은 알아야 해요."}]}},"river_alliance:rank:5":{"e":{"0":{"old":"5b0ac6ee934956287ee8595710026f66","t":"수궁의 노래를 듣고 오셨군요. 무엇을 부르는 노래였는지는… 장부에만 적어 두죠."},"1":{"old":"c2eae16c30f89074bbfd401287423e24","t":"사실 그건 장사가 아니라 부탁이었어요. 도방이 한 첫 부탁. 들어줘서 고마워요."}},"d":{},"ins":{}},"black_lotus:join:1":{"e":{"2":{"old":"8361fd5362684d4f99c7a1578d32fccf","t":"들어오려면 계약금 삼백 전을 내시고, 작은 빚도 하나 지셔야 해요. 그래야 우리가 손님을 믿죠."}},"d":{},"ins":{"3":[{"s":"black_lotus:six","t":"그 빚은 돈으로는 못 갚는다. 정보로 갚아라."},{"s":"black_lotus:six","t":"어디서든 탐색을 두 번 하고, 탐색에서 단서 하나를 건져 와라. 정청이 숨기는 것일수록 비싸다. 가져올 곳은 여기다."}]}},"black_lotus:join:2":{"e":{"0":{"old":"ecdeb11e4a0a5242e96231aa509be110","t":"가져왔나. 보여라."}},"d":{"1":"c32039390daab332afae97ec22f3bc0d"},"ins":{"2":[{"s":"black_lotus:six","t":"기록에 없는 것이다. 값이 나간다."}],"3":[{"s":"black_lotus:guseul","t":"회주님이 열세 번째 문 앞에서 기다리세요. 열두 문을 지나, 아무도 세지 않는 문으로 오세요."}]}},"black_lotus:rank:2":{"e":{"0":{"old":"242d006414f4ae2f1c0ab02055b0b0a8","t":"만인장에 다녀오셨네요. 지워진 이름, 누가 샀는지 찾으셨어요?"}},"d":{},"ins":{"2":[{"s":"black_lotus:six","t":"다음. 정청 장부와 우리 장부가 같은 일을 다르게 적었다. 평판 팔백이 되면 거래소에서 한 번 사고팔아 숫자를 맞춰 보고, 세 번 탐색해 틀린 쪽을 찾아라."}]}},"black_lotus:rank:3":{"e":{"0":{"old":"ede6d990f4890869885a080ce6b7844b","t":"숫자는 맞춰 봤나. 어느 쪽이 틀렸지."}},"d":{},"ins":{"3":[{"s":"black_lotus:six","t":"회주께서 부르신다. 평판이 천육백에 닿으면 무명 고도 원정을 끝까지 다녀와라. 폐궁의 문을 보고 오라는 분부다."}]}},"black_lotus:rank:4":{"e":{"0":{"old":"4c9f414de231f7703da5e41818654dc3","t":"폐궁의 문을 보았느냐. 아직 열 때가 아니다. 다만 문지기는 문을 알아야 한다."}},"d":{},"ins":{"2":[{"s":"black_lotus:mumyeong","t":"평판이 삼천에 닿거든 열세 번째 문 앞으로 오너라. 흑련의 뿌리를 일러 주마."}]}},"north_league:join:1":{"e":{"2":{"old":"c227ba1ba1c7b6e09e04b3dfc2e78852","t":"말로는 아무나 맹세한다. 길 위에서 보여 줘라. 이 짐을 지고 두 번 길을 옮기고, 짐을 노리는 요괴 셋을 쓰러뜨려라."}},"d":{},"ins":{"2":[{"s":"north_league:yeo","t":"짐을 지켜 냈으면 이 산문으로 돌아와 보고해라."}]}},"north_league:join:2":{"e":{"3":{"old":"4e1006a16e6c786edb16bac181b38edf","t":"맹주께서 종각 아래에서 기다리십니다. 손이 먼저 나가는 분이니, 놀라지 마시고."}},"d":{},"ins":{}},"north_league:rank:2":{"e":{"0":{"old":"515cdc86bc043cb0ed8fbe501a9f82fb","t":"관문의 깃발을 뽑고, 꽂은 놈들 다섯도 쓰러뜨렸군."}},"d":{},"ins":{"2":[{"s":"north_league:yeo","t":"다음은 옥문 협로다. 평판이 팔백이 되면 피난민 행렬이 지날 그 길을 원정으로 끝까지 다녀와라. 우리가 앞에 서고, 뒤에 서고, 옆에 선다."}]}},"north_league:rank:3":{"e":{"0":{"old":"b3079ca42d524207298eb5d2594b221f","t":"행렬은 무사히 협로를 지났다. 네가 길을 끝까지 열어 둔 덕이다."}},"d":{},"ins":{"2":[{"s":"north_league:hyegak","t":"얼음 인장에 금이 갔습니다. 평판이 천육백이 되면 빙혼곡에서 세 번 채집해 언 얼음을 가져오시고, 천경호를 두 번 살펴 물이 어디서 녹아드는지 봐 주십시오."}]}},"north_league:rank:4":{"e":{"0":{"old":"25eda56c83ebf4718d47c1a28804fc18","t":"빙혼곡 얼음과 천경호 소식, 잘 받았습니다. 녹은 얼음을 다시 얼릴 수는 없지만, 더 녹지 않게는 할 수 있지요."}},"d":{},"ins":{"2":[{"s":"north_league:seok","t":"평판이 삼천이 되면 뇌명봉 꼭대기로 올라와라. 거기 버티는 우두머리를 쓰러뜨려라. 기다리겠다."}]}},"north_league:rank:5":{"e":{"0":{"old":"7847d67e93ed0448063d8af6dbf2c742","t":"벼락이 그치지 않는 봉우리 꼭대기. 쓰러진 우두머리 너머에서 노인이 기다리고 있다."}},"d":{},"ins":{}},"mandate_court:join:1":{"e":{"2":{"old":"9abec6a48eb1c04970bb9c1cd9012047","t":"하늘의 변화는 땅에 먼저 내려와요. 서로 다른 지역 세 곳에서 한 번씩 탐색하고 와요. 날씨, 시간, 요기의 흐름까지 적어서요."}},"d":{},"ins":{"2":[{"s":"mandate_court:seo","t":"다 되면 여기 정청이나 무극 관성대로 와요. 저는… 아마 깨어 있을 거예요."}]}},"mandate_court:rank:2":{"e":{"0":{"old":"3d1c4790c001edc0b079c3bc09c1c697","t":"삼경까지 깨어 있었네요. 졸렸죠? 나도 참았어요. 그래서, 뭐가 보였어요?"}},"d":{},"ins":{"2":[{"s":"mandate_court:mun","t":"날씨가 사나운 날에만 남는 흔적이 있다. 평판 팔백이 되면 농무나 삭풍, 혈무가 낀 날 원정을 끝까지 다녀와라. 그날의 기록이 필요하다."}]}},"mandate_court:rank:3":{"e":{"0":{"old":"90be995567f34cf55ca2abcc70e8e82f","t":"사나운 날의 기록이군. 받아 두겠다."}},"d":{},"ins":{"2":[{"s":"mandate_court:mun","t":"태사령께서 분부를 남기셨다. 평판이 천육백이 되면 백옥 천문탑에서 세 번 탐색해, 거울이 흐려진 것인지 하늘이 흐려진 것인지 알아 오라 하신다."}]}},"mandate_court:rank:4":{"e":{"0":{"old":"b276a7a54284177f9f272549493185c5","t":"천문탑에 다녀왔느냐. 흐려진 것이 거울이더냐, 하늘이더냐."}},"d":{},"ins":{"2":[{"s":"mandate_court:hahu","t":"하늘이 흐려졌다면 때가 가깝다. 평판이 삼천에 이르면 무극 관성대로 오너라."}]}},"southern_remnant:join:1":{"e":{"2":{"old":"c85220148181a6162f2122c3830bd7a2","t":"…진심이야? 그럼 마을을 지켜 봐. 밤마다 재 속에서 뭔가가 기어 나와. 요괴 셋을 쓰러뜨리고, 화로에 넣을 걸 두 번 채집해서 여기로 가져와."}},"d":{},"ins":{}},"southern_remnant:join:2":{"e":{"3":{"old":"8e6d34944967195de2fe2cc4577cb0a3","t":"장군께서 마을 한가운데 꺼지지 않는 화로 앞에서 뵙자 하시오. 남은 한 팔로 그대를 맞으실 게요."}},"d":{},"ins":{}},"southern_remnant:rank:2":{"e":{"0":{"old":"e5d031fc9cbe1bf1e41591d7296b26d0","t":"재의 해안에서 기와를 건져 오셨구려. 어디 보십시다."}},"d":{},"ins":{"2":[{"s":"southern_remnant:galmae","t":"다음은 혈엽림이야. 평판 팔백 되면 가. 옛날에 뭔가를 매달았던 쇠사슬이 묻혀 있대. 지키는 놈들 다섯을 치우고, 두 번 채집해서 파내. 누가 파 가기 전에."}]}},"southern_remnant:rank:3":{"e":{"0":{"old":"eb6d7ad278148f2a07c03bee0e51e8c4","t":"사슬, 파냈어? …그래서, 끝에 뭐가 달려 있었는데."}},"d":{},"ins":{"2":[{"s":"southern_remnant:galmae","t":"장군님 부탁이야. 평판 천육백 되면 주혈 광산 원정을 끝까지 다녀와 줘. 광산에서 망자들이 일어났대. 우리 병사들이래."}]}},"southern_remnant:rank:4":{"e":{"0":{"old":"d70f6de682c0a80aa1a4a92ec29c399d","t":"광산의 망자들을 다시 눕혔다고 들었다. 우리 병사들이었다."},"1":{"old":"20165693e3d408f238259fc28f433b47","t":"…이번엔 편히 누웠겠지."}},"d":{},"ins":{"2":[{"s":"southern_remnant:soi","t":"평판이 삼천에 닿으면 구등대 군도로 가시오. 망국의 마지막 날부터 한 번도 꺼진 적 없는 등불이 아직 남아 있소. 세 번 살펴 그 불이 무사한지 보고 오시오."}]}},"southern_remnant:rank:5":{"e":{"0":{"old":"21af686b89bacc30710c0fe28ec2e978","t":"그 불이 아직 살아 있었구려. 등대지기가 섬을 돌아가며 지켜 온 불이오. 망국의 마지막 날부터 한 번도 꺼진 적 없소."}},"d":{},"ins":{}},"black_lotus:join:3":{"e":{"2":{"old":"94206eb593184baccbaffb1417c6a48e","t":"남들은 내가 이름을 팔았다고 한다. 판 게 아니라 이 회원 장부에 통째로 맡겨 둔 것이다. 그래서 무명이라 불리지. 너에게 그만큼을 바라진 않는다."},"3":{"old":"66ebe3fdaa3bc05017db1d755adadb1e","t":"이름의 한 글자만 맡겨라. 여기 식구들은 이름 대신 호칭으로 불리고, 맡긴 이름은 정청과 따로 두는 이 장부가 지키니 흩어질 일은 없다. 그 글자로 불리면 한 박자 늦게 돌아보겠지만, 네가 배신하지 않는 한 아무도 꺼내지 않는다."}},"d":{},"ins":{"4":[{"s":"black_lotus:guseul","t":"평판이 삼백쯤 쌓이면 일을 드릴게요. 만인장 비석 중에 이름이 지워진 게 있어요. 거기서 세 번쯤 탐색해서 누가 그 이름을 샀는지 알아 와 주세요."}]}},"night_office:join:3":{"e":{"3":{"old":"b110a4a316ac212ab8064fb81606e4e2","t":"이름을 적는 것은 그것을 붙잡아 두는 일이네. 적힌 이름은 명줄 한 가닥이지. 자네 이름도 이제 이 장부에 남네."}},"d":{},"ins":{"6":[{"s":null,"t":"방을 나서자 모가람이 문 앞에서 기다리고 있다."},{"s":"night_office:mo","t":"평판이 삼백쯤 쌓이면 첫 일을 드릴게요. 장서각 지하서고에 먹 색이 다른 장부가 하나 더 있대요. 두 번은 뒤져야 찾을 거예요."}]}},"night_office:join:2":{"e":{},"d":{},"ins":{"5":[{"s":"night_office:mo","t":"참, 도제조님이 정청 가장 안쪽 방에서 기다리세요. 이 장부를 들고 지금 바로 가 보세요."}]}},"red_moon_cult:join:3":{"e":{},"d":{},"ins":{"5":[{"s":"red_moon_cult:danbi","t":"입교를 축하해요. 평판이 삼백쯤 쌓이면 혈서를 쓰게 될 텐데, 먹이 모자라요. 그때 유리협곡 절벽의 붉은 결정을 세 번쯤 채집해 와 주세요."}]}},"red_moon_cult:rank:4":{"e":{},"d":{},"ins":{"2":[{"s":"red_moon_cult:wolhwa","t":"평판이 삼천에 이르면 백골 장터의 붉은 등 아래로 오너라. 장로가 될 자에게만 하는 말이 있다."}]}},"river_alliance:join:2":{"e":{},"d":{},"ins":{"2":[{"s":"river_alliance:nodeul","t":"자, 이제 도방한테 가 봐. 나루에 묶인 연맹 큰 배 위에서 기다린다. 서명만 하면 끝이야."}]}},"river_alliance:join:3":{"e":{},"d":{},"ins":{"4":[{"s":"river_alliance:maehyang","t":"연맹 일거리는 평판 삼백부터 드려요. 첫 일은 염등촌이에요. 소금 등잔 기름이 떨어졌대요. 염등촌까지 가서 세 번 채집해 기름감을 대 주세요."}]}},"north_league:join:3":{"e":{},"d":{},"ins":{"5":[{"s":"north_league:yeo","t":"맹약을 맺었으니 일을 맡긴다. 평판이 삼백이 되면 회산 관문으로 가라. 붉은 달 문양 깃발이 꽂혔다. 깃발을 뽑고, 꽂은 놈들 다섯을 쓰러뜨려라."}]}},"mandate_court:join:2":{"e":{},"d":{},"ins":{"2":[{"s":"mandate_court:mun","t":"태사령께서 혼천의 앞에서 기다리신다. 기록을 들고 가라."}]}},"mandate_court:join:3":{"e":{},"d":{},"ins":{"4":[{"s":"mandate_court:seo","t":"관측생이 됐으니 밤샘도 해야죠. 평판이 삼백쯤 쌓이면 삼경, 그러니까 자정부터 새벽 여섯 시 사이에 두 번 탐색해 봐요. 삼경의 별은 낮에 안 보이는 걸 보여 줘요."}]}},"southern_remnant:join:3":{"e":{},"d":{},"ins":{"5":[{"s":"southern_remnant:soi","t":"평판이 삼백쯤 쌓이면 재의 해안으로 가 보시오. 재 속에 옛 왕궁의 기와 조각이 묻혀 있소. 세 번은 뒤져야 하나라도 건질 게요."}]}},"night_office:rejoin:1":{"e":{},"d":{},"ins":{"1":[{"s":"night_office:mo","t":"다시 일을 드릴게요. 평판이 삼백쯤 다시 쌓이면 장서각 지하서고를 두 번 뒤져 봐요. 먹 색이 다른 장부가 하나 더 있대요."}]}},"black_lotus:rejoin:1":{"e":{},"d":{},"ins":{"1":[{"s":"black_lotus:guseul","t":"다만 장부는 처음부터예요. 평판이 삼백쯤 다시 쌓이면 만인장에서 세 번 탐색해 주세요. 비석 중에 이름이 지워진 게 있는데, 누가 그 이름을 샀는지 알아 와야 해요."}]}},"mandate_court:rejoin:1":{"e":{},"d":{},"ins":{"1":[{"s":"mandate_court:seo","t":"관측도 처음부터 다시예요. 평판이 삼백쯤 쌓이면 삼경, 그러니까 자정부터 새벽 여섯 시 사이에 두 번 탐색해 봐요. 졸려도 참고요."}]}},"north_league:rejoin:1":{"e":{},"d":{},"ins":{"1":[{"s":"north_league:yeo","t":"맹약을 다시 맺었으니 일도 처음부터다. 평판이 삼백이 되면 회산 관문으로 가라. 붉은 달 문양 깃발이 또 꽂혔다. 깃발을 뽑고, 꽂은 놈들 다섯을 쓰러뜨려라."}]}},"red_moon_cult:rejoin:1":{"e":{},"d":{},"ins":{"1":[{"s":"red_moon_cult:danbi","t":"돌아왔으니 혈서부터 다시 써야죠. 평판이 삼백쯤 쌓이면 유리협곡 절벽의 붉은 결정을 세 번쯤 채집해 와 주세요. 먹이 늘 모자라거든요."}]}},"river_alliance:rejoin:1":{"e":{},"d":{},"ins":{"1":[{"s":"river_alliance:maehyang","t":"일거리는 평판 삼백부터 다시 드려요. 첫 일은 또 염등촌이에요. 염등촌까지 가서 세 번 채집해 소금 등잔 기름감을 대 주세요."}]}},"southern_remnant:rejoin:1":{"e":{},"d":{},"ins":{"1":[{"s":"southern_remnant:soi","t":"평판이 삼백쯤 다시 쌓이면 재의 해안으로 가 보시오. 재 속에 옛 왕궁의 기와 조각이 묻혀 있소. 세 번은 뒤져야 하나라도 건질 게요."}]}}}'::jsonb;
  go jsonb := '{"mq_nine_gates/4":"회생 부적을 만들고 원정을 끝까지 다녀와 구중 봉연에 닿는다","sq_river_ferry_2/3":"그림자 뱃사공 두 마리를 쓰러뜨리고 단서 하나 찾기","sq_salt_village_1/2":"소금각시 한 마리와 염전 갈매기 두 마리 쓰러뜨리기","sq_mirror_pavilion_1/2":"수경루에서 귀경 파편 세 번 채집하기","sq_mirror_pavilion_1/3":"물거울 요정을 물리치고 요기 결정을 모아 귀경 파편과 함께 건네기","sq_red_plain_2/2":"주사 광물과 비취 파편을 캔다","sq_red_plain_2/3":"주사 광물과 비취 파편을 넘긴다","sq_glass_canyon_1/2":"영유리와 요기 결정을 모아 영유리를 건넨다","sq_ash_mountain_1/2":"생 월철을 네 번, 월철 광석을 두 번 캔다","sq_crimson_mine_2/2":"주혈 광산에서 월철 광석 세 번, 생 월철 두 번 채집하기","sq_crimson_mine_2/3":"잔불촌에서 광석과 생 월철을 건네기","sq_iron_monastery_1/2":"옥문 협로에서 잔도 매복귀와 잔도 바람귀를 둘씩 쓰러뜨리고 행자를 찾는다","sq_thunder_peak_1/2":"뇌명봉에서 응축 영핵과 요기 결정을 세 번씩 캐고 영핵 둘을 넘긴다","sq_white_tower_1/3":"별빛 나비 떼를 쫓고 귀경 파편을 두 번 채집해 성진사 둘을 건넨다","rq_old_prison/3":"빙의된 죄수를 2번 쓰러뜨리고 마춘에게 황지 3장을 건넨다","rq_tide_gate/2":"만조의 갑문에서 물고기를 2번 낚고 수귀 비늘을 3개 거둔다","rq_tide_gate/3":"조막심에게 가공 부적목 2개를 건네고 도르래 집게를 3번 쓰러뜨린다","rq_crimson_altar/3":"적월 제단터에서 주사 광물을 3개 거두어 소매에게 건넨다","rq_snow_hollow/2":"서리 족제비를 3번 쓰러뜨리고 곰배 영감에게 요수 가죽 2장을 건넨다","rq_snow_hollow/3":"설피골에서 월광 이끼를 3번 거둔다","jq_analyst/2":"백지교에서 정제 황지를 3번, 연무장·팔괘진에서 부적목을 3번 거둬 둘씩 건넨다","jq_analyst/3":"월철 주괴를 2번, 장비 수리 도구를 1번 만들어 주괴를 건넨다","aq_archivebureau/2":"장서각 지하서고에서 먹정을 2번 거두고 책벌레 요괴를 2번 쓰러뜨린다","rq_lamp_alley/3":"등잔 그늘 소매치기귀를 2번 쓰러뜨리고 쇳대에게 영사 1개를 건넨다","rq_star_hill/3":"별바라기 언덕에서 운면을 2번 거둔다","rq_water_clock/2":"물시계 터에서 영유리를 2번 거두고 누리에게 생 월철 3개를 건넨다","rq_comet_crater/2":"혜성 낙하지에서 성진사를 2번 거둔다","hs_byeolchae/1":"본부 객사의 살림꾼 순덕에게 말을 겁니다."}'::jsonb; sg jsonb := '{}'::jsonb; ne jsonb := '{"sq_ash_mountain_1/2":{"new":{"at":["ash_mountain"],"tasks":[{"n":4,"r":["ash_mountain"],"t":"gather","items":["raw_iron"]},{"n":2,"r":["ash_mountain"],"t":"gather","items":["ore"]}]},"old":{"at":["ash_mountain"],"tasks":[{"n":4,"r":["ash_mountain"],"t":"gather","items":["raw_iron"]},{"n":2,"r":["ash_mountain"],"t":"gather","items":["steel_ingot"]}]}},"sq_ash_mountain_1/3":{"new":{"at":["ash_mountain"],"give":{"raw_iron":4,"ore":2}},"old":{"at":["ash_mountain"],"give":{"raw_iron":4,"steel_ingot":2}}},"sq_crimson_mine_2/2":{"new":{"at":["crimson_mine"],"tasks":[{"n":3,"r":["crimson_mine"],"t":"gather","items":["ore"]},{"n":2,"r":["crimson_mine"],"t":"gather","items":["raw_iron"]}]},"old":{"at":["crimson_mine"],"tasks":[{"n":3,"r":["crimson_mine"],"t":"gather","items":["ore"]},{"n":2,"r":["crimson_mine"],"t":"gather","items":["steel_ingot"]}]}},"sq_crimson_mine_2/3":{"new":{"at":["ember_village"],"give":{"ore":3,"raw_iron":2},"tasks":[{"n":1,"r":["ember_village"],"t":"travel"}]},"old":{"at":["ember_village"],"give":{"ore":3,"steel_ingot":2},"tasks":[{"n":1,"r":["ember_village"],"t":"travel"}]}}}'::jsonb; np jsonb := '[{"npc_key":"q:hs_bomi","npc_name":"객사 살림꾼 순덕","bio":"본부 객사의 살림을 맡은 사람. 손님 방부터 뒤뜰 장독까지 모르는 것이 없다. 오래 비어 있던 별채를 아까워한다.","old_name":"객사 살림꾼 보미"}]'::jsonb;
  e record; p text[]; k int; bad text;
begin
  if exists (select 1 from public.world_app_meta where key = 'quest_lines_744') then raise notice '이미 적용됨'; return; end if;
  for e in select key, value from jsonb_each(st) loop
    p := string_to_array(e.key, '/');
    update public.world_quest_steps set lines = pg_temp.yh744_rebuild(lines, e.value, e.key) where quest_id = p[1] and step = p[2]::int;
    get diagnostics k = row_count; if k <> 1 then raise exception '장면 없음 %', e.key; end if;
  end loop;
  for e in select key, value from jsonb_each(ep) loop
    update public.world_quests set epilogue = pg_temp.yh744_rebuild(epilogue, e.value, e.key || '/결말') where quest_id = e.key;
    get diagnostics k = row_count; if k <> 1 then raise exception '퀘스트 없음 %', e.key; end if;
  end loop;
  for e in select key, value from jsonb_each(sc) loop
    update public.world_faction_scenes set lines = pg_temp.yh744_rebuild(lines, e.value, e.key) where scene_key = e.key;
    get diagnostics k = row_count; if k <> 1 then raise exception '세력 장면 없음 %', e.key; end if;
  end loop;
  for e in select key, value #>> '{}' as v from jsonb_each(go) loop
    p := string_to_array(e.key, '/');
    update public.world_quest_steps set goal = e.v where quest_id = p[1] and step = p[2]::int;
    get diagnostics k = row_count; if k <> 1 then raise exception '장면 없음(goal) %', e.key; end if;
  end loop;
  for e in select key, value #>> '{}' as v from jsonb_each(sg) loop
    update public.world_faction_scenes set goal = e.v where scene_key = e.key;
    get diagnostics k = row_count; if k <> 1 then raise exception '세력 장면 없음(goal) %', e.key; end if;
  end loop;
  for e in select key, value from jsonb_each(ne) loop
    p := string_to_array(e.key, '/');
    update public.world_quest_steps set need = e.value -> 'new' where quest_id = p[1] and step = p[2]::int and need = e.value -> 'old';
    get diagnostics k = row_count; if k <> 1 then raise exception '할 일 조건이 DB와 다름 %', e.key; end if;
  end loop;
  for e in select value from jsonb_array_elements(np) loop
    update public.world_quest_npcs set npc_name = e.value ->> 'npc_name', bio = coalesce(e.value ->> 'bio', bio) where npc_key = e.value ->> 'npc_key';
    get diagnostics k = row_count; if k <> 1 then raise exception '인물 없음 %', e.value ->> 'npc_key'; end if;
  end loop;
  -- 말하는 이: 서술(null)이거나 아는 인물만, 주인공('me')은 없음
  select string_agg(distinct l ->> 's', ', ') into bad from (
      select jsonb_array_elements(lines) l from public.world_quest_steps
      union all select jsonb_array_elements(lines) from public.world_faction_scenes
      union all select jsonb_array_elements(epilogue) from public.world_quests where jsonb_typeof(epilogue) = 'array') x
    where l ->> 's' is not null and l ->> 's' not in (select npc_key from public.world_quest_npcs union select npc_key from public.world_faction_npcs);
  if bad is not null then raise exception '모르는 말하는 이: %', bad; end if;
  insert into public.world_app_meta(key, value) values ('quest_lines_744', now()::text);
end $do$;
